/* PATHOLOGIES — div = divergences entre sociétés (SFAR/SRLF privilégiée, signalée) */
window.PATHO = [
{id:'pavm', cat:'Respiratoire', name:'Pneumonie acquise sous ventilation mécanique (PAVM) / pneumonie nosocomiale', site:'pulm',
 epi:'Infection la plus fréquente en réanimation (≈ 10–20 % des patients ventilés > 48 h). Précoce (< 5 j) : flore communautaire (S. aureus SAMS, pneumocoque, H. influenzae, entérobactéries sauvages). Tardive (≥ 5 j) ou FdR : P. aeruginosa, entérobactéries BLSE/AmpC, SARM, Acinetobacter, S. maltophilia.',
 semio:'Nouvel infiltrat radiologique + ≥ 2 parmi : fièvre > 38,3 °C ou hypothermie, hyperleucocytose ou leucopénie, sécrétions purulentes, dégradation de l\'oxygénation. Trachéobronchite (sans infiltrat) : pas d\'antibiothérapie recommandée (SFAR/SRLF 2017).',
 diag:'Prélèvement respiratoire AVANT toute (modification d\')antibiothérapie : aspiration trachéale quantitative (≥ 10⁵–10⁶ UFC/mL), mini-LBA/LBA (≥ 10⁴), brosse/PDP (≥ 10³). Examen direct (Gram) utile pour orienter. Hémocultures. PCR multiplex pneumonie (FilmArray®) : identification + gènes de résistance (mecA, CTX-M, carbapénémases) en 1 h — utile pour désescalade rapide.',
 proba:'<b>Monothérapie</b> par β-lactamine chez l\'immunocompétent, sauf choc septique ou risque élevé de BMR (SFAR/SRLF 2017).<ul><li><b>Précoce sans FdR</b> : céfotaxime/ceftriaxone ou amox-clav.</li><li><b>Tardive ou FdR de BMR</b> (antibiothérapie < 90 j, hospitalisation ≥ 5 j, colonisation connue, écologie locale) : β-lactamine anti-Pseudomonas (pip-tazo, céfépime, ceftazidime) ; <b>carbapénème</b> si colonisation/infection BLSE < 3 mois + gravité (HAS 2019).</li><li><b>+ amikacine</b> 1–3 j si choc septique ou forte prévalence de BMR.</li><li><b>+ anti-SARM</b> (vancomycine ou linézolide) si colonisation SARM ou forte prévalence locale.</li></ul>',
 doc:'Désescalade dès l\'antibiogramme (48–72 h), monothérapie y compris pour P. aeruginosa. Ne pas utiliser la daptomycine (inactivée par le surfactant), ni la tigécycline.',
 duree:'7 jours (SFAR/SRLF 2017 ; 8 j dans la RFE SRLF/SFAR 2014), y compris pour les BGN non fermentants si évolution favorable.',
 div:'Les RFE SFAR/SRLF 2017 et la HAS/SPILF/SRLF 2019 sont globalement concordantes. La procalcitonine pour raccourcir la durée : « accord faible » dans HAS 2019, jugée insuffisante seule par le comité des référentiels de la SPILF → l\'app retient la position SFAR/SRLF (PCT = aide, non critère unique).',
 refs:['sfar_pavm17','sfar_pavm17fr','has_carba19','srlf_atb14','spilf_durees21']},
{id:'pac', cat:'Respiratoire', name:'Pneumonie aiguë communautaire (PAC) grave', site:'pulm',
 epi:'S. pneumoniae (1re cause), Legionella (2e cause des formes graves), S. aureus (post-grippal, PVL), entérobactéries/H. influenzae (comorbidités), virus (grippe, VRS, SARS-CoV-2).',
 semio:'Critères de gravité (ATS/IDSA, SMART-COP) ; choc, IRA hypoxémiante.',
 diag:'Hémocultures, antigénuries pneumocoque et légionelle, prélèvement respiratoire (ECBC/AT), PCR multiplex respiratoire (cf. Examens : PCR multiplex bactérienne sur prélèvement bas, PCR bactéries atypiques Mycoplasma/Chlamydophila/Legionella) (virus, intracellulaires) dans les formes graves. CRP/PCT non recommandées pour décider de l\'antibiothérapie (SPILF/SPLF 2025).',
 proba:'<b>Réanimation</b> : C3G (céfotaxime 1–2 g q8h ou ceftriaxone 1–2 g/j) + macrolide (spiramycine 3 MUI q8h) — ou lévofloxacine en cas de suspicion forte de légionellose. FdR de P. aeruginosa (DDB, mucoviscidose, exacerbations BPCO colonisées) : β-lactamine anti-Pseudomonas. Carbapénèmes non recommandés en probabiliste quelle que soit la gravité (HAS 2019). Hydrocortisone 200 mg/j si PAC grave (SPILF/SPLF 2025).',
 doc:'Adaptation à la documentation ; arrêt du macrolide si légionellose exclue.',
 duree:'5–7 j (7 j en réanimation) ; légionellose grave 8–14 j (21 j immunodéprimé) ; S. aureus/BGN : 7–14 j selon évolution.',
 div:'Pas de recommandation SFAR spécifique ; texte SPILF/SPLF 2025 co-construit avec la SRLF.',
 refs:['spilf_pac25','has_carba19','spilf_durees21']},
{id:'inhal', cat:'Respiratoire', name:'Pneumopathie d\'inhalation', site:'pulm',
 epi:'Troubles de conscience (neuroréanimation ++), troubles de déglutition. Pneumopathie chimique (Mendelson) ≠ pneumonie bactérienne. Germes : flore oropharyngée, entérobactéries ; anaérobies rarement prépondérants hors abcès/empyème.',
 semio:'Infiltrat déclive (lobe inférieur droit, segments postérieurs).',
 diag:'Prélèvement respiratoire distal ; ne pas traiter une pneumopathie chimique isolée qui régresse en 24–48 h.',
 proba:'Communautaire : amox-clav (ou C3G). Associée aux soins/tardive : selon FdR de BMR (cf. PAVM). Couverture anti-anaérobie spécifique non nécessaire sauf abcès/empyème.',
 doc:'Selon documentation.', duree:'5–7 j.',
 div:'—', refs:['spilf_pac25','sfar_pavm17']},
{id:'iu', cat:'Urinaire', name:'Pyélonéphrite / infection urinaire grave (communautaire)', site:'uri',
 epi:'E. coli (≈ 70–80 %), autres entérobactéries, entérocoque. BLSE ≈ 5–10 %.',
 semio:'Sepsis/choc d\'origine urinaire, obstacle (urgence : drainage).',
 diag:'ECBU avant antibiotique (seuil ≥ 10³ UFC/mL E. coli ; ≥ 10⁴ autres), hémocultures, imagerie (échographie/uroscanner) à la recherche d\'un obstacle ou d\'un abcès dans les 24 h.',
 proba:'<b>Sepsis grave / choc</b> : C3G (céfotaxime de préférence) + amikacine ; si colonisation/infection BLSE < 3 mois : carbapénème + amikacine (HAS 2019). Drainage urgent d\'un obstacle.',
 doc:'Relais oral selon antibiogramme (FQ, cotrimoxazole, amox, amox-clav). BLSE : alternatives aux carbapénèmes (témocilline, pip-tazo si CMI ≤ 8, céfoxitine, aminosides, FQ/cotrimoxazole si S).',
 duree:'PNA : 7 j (FQ, C3G) ; 10 j autres molécules ; IU masculine : 14 j (raccourcissement discuté selon évolution) — SPILF 2021.',
 div:'—', refs:['spilf_recos','has_carba19','spilf_durees21']},
{id:'iuas', cat:'Urinaire', name:'ECBU positif sur sonde / infection urinaire associée aux soins', site:'uri',
 epi:'Bactériurie quasi constante après 30 j de sondage. E. coli, Enterococcus, Proteus, Klebsiella, P. aeruginosa, Candida.',
 semio:'IUAS sur sonde évoquée devant une fièvre sans autre cause identifiée, des douleurs sus-pubiennes/lombaires, ou un sepsis. La bandelette urinaire n\'est pas recommandée ; la leucocyturie n\'a pas de valeur sur sonde.',
 diag:'ECBU sur la sonde en place (ponction du site dédié après désinfection, pas de prélèvement dans le sac) ; seuil ≥ 10⁵ UFC/mL en présence d\'un dispositif endo-urinaire (SF2H/SPILF 2015). Changer la sonde avant de débuter l\'antibiothérapie (et prélever sur la nouvelle sonde).',
 proba:'<b>Colonisation (bactériurie asymptomatique) : ne pas traiter</b>, y compris en réanimation et avant ablation/changement de sonde (D-II). Ne pas dépister. Exceptions : grossesse, chirurgie urologique programmée. IUAS symptomatique : selon gravité et FdR de BMR (cf. PNA / PAVM pour les FdR). Candidurie asymptomatique : abstention.',
 doc:'Selon antibiogramme, spectre le plus étroit.',
 duree:'Cystite associée aux soins 5–7 j (3 j si < 75 ans et ablation de la sonde) ; PNA 7–10 j ; IU masculine 14 j ; IU sur matériel endo-urétéral 5–10 j.',
 div:'—', refs:['spilf_iuas15','spilf_durees21']},
{id:'bact_kt', cat:'Bactériémies', name:'Bactériémie / infection liée au cathéter (ILC)', site:'kt',
 epi:'SCN, S. aureus, entérobactéries, P. aeruginosa, Candida. Cathéters fémoraux et de dialyse à risque.',
 semio:'Signes locaux inconstants ; bactériémie sans autre foyer ; amélioration après retrait.',
 diag:'Hémocultures couplées (périphérique + cathéter) : délai différentiel de positivité ≥ 2 h en faveur d\'une ILC ; culture du cathéter retiré (≥ 10³ UFC/mL, méthode de Brun-Buisson). 2 hémocultures pour SCN.',
 proba:'Retrait du cathéter si : choc, S. aureus, P. aeruginosa, Candida, thrombophlébite suppurée, signes locaux, bactériémie persistante. Probabiliste en sepsis : vancomycine (Gram +) ± β-lactamine anti-BGN selon gravité/neutropénie/fémoral (SRLF 2020).',
 doc:'Selon germe ; verrous antibiotiques pour cathéters de longue durée conservés.',
 duree:'Après retrait : SCN 3–7 j (abstention possible si retrait et patient stable) ; entérobactéries/entérocoques 7 j ; P. aeruginosa 7–10 j ; S. aureus ≥ 14 j (4–6 sem si compliquée) ; Candida 14 j après hémocultures négatives ; thrombophlébite suppurée 3–6 sem.',
 div:'—', refs:['srlf_kt20','idsa_crbsi09','spilf_durees21']},
{id:'cervical', cat:'ORL', name:'Infections cervicales profondes (abcès ORL) : abcès péri-amygdalien, abcès para- et rétropharyngé, cellulite cervicale', site:'cerv',
 epi:'Complications des angines et rhinopharyngites, rares : <b>≈ 0,2–0,3 %</b> (<a class="recolink noabbr" href="https://infectiologie.com/UserFiles/File/spilf/recos/rpc-pharyngite-2024.pdf" target="_blank" rel="noopener">SFORL 2024</a>).<br><b>Formes</b> : adénite suppurée ; abcès péri-amygdalien (phlegmon) ; infections péripharyngées (rétropharyngées, rétro-styliennes, pré-styliennes) ; <b>cellulite cervicale profonde extensive</b>, qui peut descendre dans le médiastin (<a href="#p-mediastinite">médiastinite nécrosante descendante</a>) ; thrombose jugulaire (<a href="#p-thrombo">syndrome de Lemierre</a>).<br><b>Germes cibles</b> : streptocoques (dont SGA), S. aureus, S. pneumoniae, anaérobies (Fusobacterium, Prevotella, Peptostreptococcus, Bacteroides, Porphyromonas, Finegoldia) (<a class="recolink noabbr" href="https://infectiologie.com/UserFiles/File/spilf/recos/rpc-pharyngite-2024.pdf" target="_blank" rel="noopener">SFORL/SPILF 2024</a>).<br>Les recommandations <a class="recolink noabbr" href="https://infectiologie.com/UserFiles/File/spilf/recos/rpc-pharyngite-2024.pdf" target="_blank" rel="noopener">SFORL 2024</a> portent sur les infections <b>d\'origine pharyngée</b> ; les cellulites d\'origine dentaire (dont l\'angine de Ludwig) n\'y sont pas traitées spécifiquement.',
 semio:'<b>Torticolis fébrile</b> → évoquer une infection cervicale profonde. <b>Trismus récent</b> → infection péripharyngée.<br><b>Cellulite cervicale profonde</b> si : douleurs cervicales <b>et thoraciques</b>, érythème cutané cervical ou thoracique (<a class="recolink noabbr" href="https://infectiologie.com/UserFiles/File/spilf/recos/rpc-pharyngite-2024.pdf" target="_blank" rel="noopener">SFORL 2024</a>).<br><b>Signes de gravité</b> : dyspnée, stridor, dysphagie avec hypersalivation, sepsis ; crépitation sous-cutanée (cellulite nécrosante).',
 diag:'<b>Scanner cervico-thoracique injecté</b> : bilan d\'extension (cervical et médiastinal) et repérage des collections. Abcès péri-amygdalien typique et rapidement résolu : imagerie non utile (<a class="recolink noabbr" href="https://infectiologie.com/UserFiles/File/spilf/recos/rpc-pharyngite-2024.pdf" target="_blank" rel="noopener">SFORL 2024</a>).<br>Prélèvements par ponction ou drainage (culture aérobie et anaérobie) ; hémocultures. Une ponction blanche n\'exclut pas un abcès péri-amygdalien.<br><b>Voies aériennes</b> : risque d\'intubation difficile (trismus, œdème, déviation) → stratégie anticipée (intubation vigile sous fibroscopie, chirurgien ORL présent).',
 proba:'<table class="tbl tx"><tr><th>Situation</th><th>1re intention</th><th>Allergie</th></tr><tr><td><b>Adénite</b> (SGA, SAMS)</td><td><b>Amoxicilline-acide clavulanique</b> 80 mg/kg/j IV (4–6 perfusions) ou PO</td><td>Céfazoline 100 mg/kg/j en 3 perfusions de 60 min ; allergie grave ou croisée : clindamycine ou linézolide</td></tr><tr><td><b>Abcès péri-amygdalien, para- ou rétropharyngé</b></td><td><b>Amoxicilline-acide clavulanique</b> 100 mg/kg/j (acide clavulanique ≤ 1,2 g/24 h). Choc septique : <b>+ gentamicine</b> 6–7 mg/kg dose unique</td><td>Céfazoline + métronidazole 500 mg × 3/j ; allergie grave ou croisée : linézolide 600 mg × 2/j</td></tr><tr><td><b>Adénite suppurée grave, cellulite cervicale, médiastinite descendante</b></td><td><b>Amoxicilline-acide clavulanique</b>, ou <b>céfotaxime</b> 100 mg/kg/j (perfusions de 4 h) / ceftriaxone <b>+ métronidazole</b> 500 mg × 3/j. Choc septique : + gentamicine dose unique. <b>+ clindamycine</b> si évolution rapide ou signes toxiniques (éruption, troubles digestifs, confusion, hypotension)</td><td>C3G + métronidazole ; allergie grave ou croisée : méropénème 2 g × 3/j (perfusions de 4 h) ± clindamycine ; allergie vraie à toutes les β-lactamines : lévofloxacine + linézolide (avis infectiologique obligatoire)</td></tr></table>Source : <a class="recolink noabbr" href="https://infectiologie.com/UserFiles/File/spilf/recos/rpc-pharyngite-2024.pdf" target="_blank" rel="noopener">SFORL/SPILF 2024</a>. Doses du protocole NAR pour les autres situations : fiches molécules.',
 doc:'Adaptation à la microbiologie ; <b>maintenir une couverture des anaérobies</b> au relais (<a class="recolink noabbr" href="https://infectiologie.com/UserFiles/File/spilf/recos/rpc-pharyngite-2024.pdf" target="_blank" rel="noopener">SFORL/SPILF 2024</a>). Relais oral dès évolution favorable (amoxicilline-acide clavulanique, clindamycine, linézolide selon l\'antibiogramme). Entérobactéries et P. aeruginosa rares.<br><b>Chirurgie</b> : drainage de toute collection (ponction ou incision pour l\'abcès péri-amygdalien, à répéter en l\'absence d\'amélioration rapide) ; cervicotomie large pour la cellulite.',
 duree:'Adénite : <b>7 j</b>. Abcès péri-amygdalien, para- ou rétropharyngé : <b>7 j si drainage, 10 j sinon</b>. Adénite suppurée grave, cellulite, médiastinite descendante : <b>14 j après la chirurgie</b> (<a class="recolink noabbr" href="https://infectiologie.com/UserFiles/File/spilf/recos/rpc-pharyngite-2024.pdf" target="_blank" rel="noopener">SFORL/SPILF 2024</a>).',
 div:'Recommandations françaises : SFORL 2024 (avec SPILF, SFM, SFCTCV et CIREOL). Lemierre associé : voir <a href="#p-thrombo">Thromboses septiques</a>.',
 refs:['sforl_cerv24','spilf_cerv24','revprat_cerv24']},
{id:'mediastinite', cat:'Thorax', name:'Médiastinites : post-sternotomie (chirurgie cardiaque), nécrosante descendante (cervicomédiastinite), post-œsophagienne', site:'medi',
 epi:'<b>Post-sternotomie</b> (chirurgie cardiaque) : infection profonde avec ostéite sternale et/ou atteinte de l\'espace rétrosternal. Incidence 0,4–5 % selon les études ; 4,07 % d\'infections du site opératoire avec reprise chirurgicale sur 7 170 sternotomies (Bichat 2006–2012). Mortalité 10–25 % selon les études (<a class="recolink noabbr" href="https://www.infectiologie.com/UserFiles/File/formation/desc/2018/seminaire-janvier-2018/cours-lundi-29.01/cc3-mediastinites-desc-2018.pdf" target="_blank" rel="noopener">DESC 2018</a>) ; <b>20,3 % en réanimation</b> sur 316 médiastinites (Pitié-Salpêtrière), plus élevée si ventilation encore nécessaire à J3 ou bactériémie persistante (Trouillet 2005).<br>Facteurs de risque : obésité, diabète (insulinotraité surtout), BPCO, immunodépression, dénutrition, insuffisance rénale, portage nasal de S. aureus ; intervention > 5 h, double pontage mammaire, reprise chirurgicale, ventilation prolongée, transfusion, urgence, séjour préopératoire > 1 semaine.<br>Microbiologie (série de Trouillet 2005, reprise dans le cours du DESC 2018) : <b>SAMS ≈ 45 %</b>, <b>SARM ≈ 15 %</b>, SCN ≈ 13 %, <b>BGN ≈ 16 %</b>, streptocoques ≈ 5 % ; polymicrobienne dans 16 % des cas.<br><b>Nécrosante descendante</b> : extension au médiastin d\'une infection pharyngée, amygdalienne, dentaire ou cervicale (<a href="#p-cervical">infections cervicales profondes</a>) ; flore streptococcique et anaérobie.<br><b>Post-œsophagienne</b> : perforation (Boerhaave, perforation endoscopique), fistule ou désunion anastomotique après œsophagectomie ; flore digestive et orale, Candida. <b>Fistule anastomotique</b> : 10 à 15 % des œsophagectomies en centre expert, responsable de 50 % des décès après intervention de Lewis-Santy (<a class="recolink noabbr" href="https://e-memoire.academie-chirurgie.fr/en/ememoire/6175-fistules-apres-chirurgie-oesogastrique-etat-des-lieux-et-comment-les-reduire" target="_blank" rel="noopener">Académie de chirurgie 2024</a>).<br><b>Candida</b> : isolé fréquemment (prélèvements pleuraux, médiastinaux, hémocultures), précocement le plus souvent, et associé à une évolution plus grave dans des séries rétrospectives (Elsayed 2012 ; Hoffmann 2013 — différence de mortalité non significative dans cette dernière) ; glissement vers des espèces non-albicans moins sensibles au fluconazole (Hoffmann 2013).',
 semio:'<b>Post-sternotomie</b> : en général entre J7 et J21 ; fièvre (≈ 40 %), écoulement ou suppuration de la cicatrice (≈ 80 %), instabilité ou douleur sternale, sepsis. <b>PCT souvent peu élevée</b> : 5 des 9 médiastinites &lt; 1 ng/mL, chez des patients déjà sous antibiotiques (Aouifi 2000) → ne pas l\'utiliser pour éliminer le diagnostic.<br><b>Nécrosante descendante</b> (critères d\'Estrera 1983) : infection sévère, images évocatrices au scanner, constatation chirurgicale ou autopsique, lien avec une infection oropharyngée ou cervicale. Douleur thoracique, dyspnée, emphysème sous-cutané après une infection cervicale.',
 diag:'<b>Post-sternotomie</b> : hémocultures (une bactériémie à S. aureus après sternotomie est très évocatrice) ; <b>ponction rétrosternale à l\'aiguille</b> (positive chez les 23 patients ayant une médiastinite, négative chez 24 des 26 indemnes ; raccourcit le délai diagnostique — Benlolo 2003) ; culture des fils de stimulation épicardiques (valeur prédictive négative élevée) ; le <b>scanner est peu sensible et peu spécifique</b> au début (collection ou air rétrosternal) ; diagnostic de certitude à la reprise chirurgicale (biopsie osseuse sternale, prélèvements rétrosternaux).<br><b>Nécrosante descendante</b> : scanner cervico-thoracique injecté.<br><b>Post-œsophagienne</b> : bilan biologique (dont lactates) ; <b>scanner injecté avec opacification œsophagienne</b> = examen de choix (WSES 2019, 1C) ; transit opaque seulement dans certains cas ; endoscopie diagnostique si le scanner est douteux, prudente (risque d\'agrandir la brèche, 1C). <b>Fistule anastomotique</b> : scanner injecté et opacifié, endoscopie si doute important ; CRP sérique et amylase dans le drain pourraient améliorer la performance diagnostique (<a class="recolink noabbr" href="https://e-memoire.academie-chirurgie.fr/en/ememoire/6175-fistules-apres-chirurgie-oesogastrique-etat-des-lieux-et-comment-les-reduire" target="_blank" rel="noopener">Académie de chirurgie 2024</a>). Prélèvements profonds (pleuraux, médiastinaux) avec <b>recherche de levures</b> à l\'examen direct ; hémocultures.',
 proba:'<b>Post-sternotomie</b> : couvrir <b>SAMS, SARM, SCN et BGN</b>, après prélèvements : <b>pipéracilline-tazobactam + vancomycine + amikacine</b>, ou <b>céfépime + vancomycine + aminoside</b> (<a class="recolink noabbr" href="https://www.infectiologie.com/UserFiles/File/formation/desc/2018/seminaire-janvier-2018/cours-lundi-29.01/cc3-mediastinites-desc-2018.pdf" target="_blank" rel="noopener">DESC 2018</a>). Adapter à l\'écologie locale (BLSE, P. aeruginosa) et aux colonisations du patient. Doses fortes : fiches molécules.<br><b>Nécrosante descendante</b> : comme les cellulites cervicales (<a class="recolink noabbr" href="https://infectiologie.com/UserFiles/File/spilf/recos/rpc-pharyngite-2024.pdf" target="_blank" rel="noopener">SFORL/SPILF 2024</a>) : amoxicilline-acide clavulanique, ou céfotaxime/ceftriaxone + métronidazole ; + gentamicine dose unique si choc ; + clindamycine si signes toxiniques ; allergie : voir la fiche <a href="#p-cervical">Infections cervicales profondes</a>. Élargir (pipéracilline-tazobactam, carbapénème) si infection associée aux soins ou BMR.<br><b>Post-œsophagienne</b> : <b>antibiothérapie à large spectre couvrant aérobies et anaérobies + IPP</b> (<a class="recolink noabbr" href="https://doi.org/10.1186/s13017-019-0245-2" target="_blank" rel="noopener">WSES 2019</a>, 1C). <b>Aucun schéma validé</b> : une revue de 77 publications (1979–2017) ne retrouve aucun essai randomisé, avec des molécules et des durées très hétérogènes (Gregory 2018). Pas de recommandation française. Proposition par <b>extrapolation de la <a class="recolink noabbr" href="https://sfar.org/prise-en-charge-therapeutique-des-infections-intra-abdominales-de-ladulte/" target="_blank" rel="noopener">RFE SFAR 2026</a> IIA</b> (voir <a href="#p-iia">Infections intra-abdominales</a>) :<br>• <b>Boerhaave, perforation communautaire</b> : céfotaxime ou ceftriaxone + métronidazole ; <b>pipéracilline-tazobactam</b> si choc septique ; carbapénème si choc avec FdR de BLSE.<br>• <b>Perforation iatrogène à l\'hôpital, fistule anastomotique post-œsophagectomie</b> : comme une IIA associée aux soins ou post-opératoire : <b>céfépime + métronidazole</b> (ou pipéracilline-tazobactam) ; <b>imipénème ou méropénème</b> si ≥ 2 FdR de BMR, ou ≥ 1 avec sepsis/choc ; anti-entérocoque (linézolide, vancomycine, teicoplanine) selon les FdR.<br><b>Antifongique</b> : pas de recommandation spécifique. Séries rétrospectives : antifongique empirique précoce à envisager devant une perforation avérée (Elsayed 2012) ; ou s\'il y a Candida + FdR (immunodépression, neutropénie, séjour prolongé en réanimation), avec <b>échinocandine en première intention</b> (Hoffmann 2013). Extrapolation <a class="recolink noabbr" href="https://sfar.org/prise-en-charge-therapeutique-des-infections-intra-abdominales-de-ladulte/" target="_blank" rel="noopener">RFE SFAR 2026</a> : levures à l\'examen direct, ou ≥ 3 critères du score péritonite (dont l\'origine sus-mésocolique) ; <b>échinocandine</b> si complication post-opératoire ou FdR de souche fluconazole-R, sinon fluconazole. Doses fortes : fiches molécules.<br><b>Mesures associées</b> (WSES 2019) : à jeun strict (1C) ; nutrition entérale ou parentérale précoce (1C) ; sonde nasogastrique posée sous endoscopie (2A) ; jéjunostomie d\'alimentation lors de la chirurgie.',
 doc:'Selon l\'antibiogramme. SAMS : cloxacilline ou céfazoline (voir la comparaison dans la fiche céfazoline). SARM : vancomycine (alternatives selon CMI : daptomycine, linézolide). BGN : selon l\'antibiogramme (voir les fiches germes).<br><b>Chirurgie urgente</b> (post-sternotomie) : réouverture de toute la sternotomie, ablation des fils d\'acier, débridement, évacuation du pus, prélèvements osseux ; puis irrigation-drainage, drains ou traitement par pression négative (TPN), lambeaux si besoin (<a class="recolink noabbr" href="https://www.infectiologie.com/UserFiles/File/formation/desc/2018/seminaire-janvier-2018/cours-lundi-29.01/cc3-mediastinites-desc-2018.pdf" target="_blank" rel="noopener">DESC 2018</a>). Nécrosante descendante : cervicotomie et drainage médiastinal et pleural (thoracoscopie ou thoracotomie).<br><b>Perforation œsophagienne</b> (WSES 2019) : traitement non opératoire seulement si patient stable, vu tôt (&lt; 24 h), sans sepsis, perforation cervicale ou thoracique <b>contenue</b>, sans pathologie œsophagienne préexistante, avec une équipe chirurgicale et radiologique disponible 24 h/24 (1C) ; clips endoscopiques pour les petites brèches (&lt; 2 cm), prothèse couverte (2 à 4 semaines) pour les plus grandes ; sinon <b>chirurgie le plus tôt possible</b> (1C) : réparation, renforcement, drainage médiastinal et pleural ; exclusion ou résection si la réparation est impossible. Drainage percutané des collections. Le retard thérapeutique est le principal facteur de mortalité (plus élevée au-delà de 24 h).<br><b>Fistule anastomotique post-œsophagectomie</b> : pas de consensus ; prise en charge active et adaptée à la gravité, endoscopique (prothèse couverte, thérapie endoscopique par pression négative), radiologique (drainage) ou chirurgicale (<a class="recolink noabbr" href="https://e-memoire.academie-chirurgie.fr/en/ememoire/6175-fistules-apres-chirurgie-oesogastrique-etat-des-lieux-et-comment-les-reduire" target="_blank" rel="noopener">Académie de chirurgie 2024</a>). Adapter l\'antibiothérapie aux prélèvements profonds ; garder la couverture des anaérobies.',
 duree:'<b>Post-sternotomie avec ostéite sternale</b> (± endocardite) : <b>6 semaines</b>, dont environ 3 semaines IV (durée IV non tranchée) (<a class="recolink noabbr" href="https://www.infectiologie.com/UserFiles/File/formation/desc/2018/seminaire-janvier-2018/cours-lundi-29.01/cc3-mediastinites-desc-2018.pdf" target="_blank" rel="noopener">DESC 2018</a>). Sans ostéite : non fixée par la source.<br><b>Nécrosante descendante</b> : <b>14 j après la chirurgie</b> (<a class="recolink noabbr" href="https://infectiologie.com/UserFiles/File/spilf/recos/rpc-pharyngite-2024.pdf" target="_blank" rel="noopener">SFORL/SPILF 2024</a>).<br><b>Post-œsophagienne</b> : <b>non fixée</b> (pas de consensus, <a class="recolink noabbr" href="https://doi.org/10.1186/s13017-019-0245-2" target="_blank" rel="noopener">WSES 2019</a> ; aucun essai, Gregory 2018). Repères :<br>• extrapolation <a class="recolink noabbr" href="https://sfar.org/prise-en-charge-therapeutique-des-infections-intra-abdominales-de-ladulte/" target="_blank" rel="noopener">RFE SFAR 2026</a> IIA (qui ne couvre pas le médiastin) : une infection après chirurgie programmée y est une IIA associée aux soins (champ 1) → <b>4 j sans sepsis, 8 j avec sepsis ou choc</b> après contrôle de la source (R2.2.4–R2.2.5) ; complication après une première intervention pour infection : 8 j après contrôle de la source et amélioration, au-delà discussion multidisciplinaire (R3.3.4) ; antifongique débuté d\'emblée avec culture à Candida : <b>8 j</b> si source contrôlée rapidement, évolution favorable et pas de candidémie (R2.3.1) ;<br>• revue narrative (Predescu 2025) : au moins 10–14 j, jusqu\'à 4 semaines dans les formes graves ;<br>• empyème associé : voir <a href="#p-empyeme">Empyème pleural</a> ; candidémie : voir <a href="#p-cand">Candidémie</a>.<br>En pratique : durée guidée par le contrôle de la source (brèche fermée ou exclue, collections drainées), à rediscuter en équipe.',
 div:'<b>Post-œsophagienne</b> : aucune recommandation française ni essai randomisé ; la RFE SFAR 2026 se limite aux infections intra-abdominales (le médiastin n\'entre pas dans son champ) : les schémas proposés en sont une extrapolation, à valider avec l\'équipe (chirurgiens). Pas de recommandation française dédiée aux médiastinites post-sternotomie : synthèse du cours du DESC de maladies infectieuses 2018 et séries françaises (Bichat). <b>Prévention</b> : décolonisation de S. aureus recommandée en chirurgie cardiaque (mupirocine nasale ± antiseptique cutané et oropharyngé).',
 refs:['revest_desc18','trouillet05','benlolo03','aouifi00','sforl_cerv24','spilf_cerv24','estrera_dnm24','wses_oeso19','sfar_iia26','gregory18','elsayed12','hoffmann13','predescu25','voron_acad24']},
{id:'idv', cat:'Ostéo-articulaire', name:'Infections disco-vertébrales et rachidiennes : spondylodiscite, épidurite et abcès épidural, infection du site opératoire du rachis (avec ou sans matériel)', site:'os',
 epi:'Recommandations françaises : <a class="recolink noabbr" href="https://doi.org/10.1016/j.idnow.2023.01.007" target="_blank" rel="noopener">SPILF 2022</a> (mise à jour de 2007), pour le rachis natif et instrumenté. Le terme « infection disco-vertébrale » regroupe le disque, les vertèbres, l\'épidurite, l\'abcès des parties molles et les infections après chirurgie avec ou sans matériel.<br><b>Germes</b> (données françaises) : S. aureus 41 %, staphylocoques à coagulase négative 17 %, streptocoques 12 %, entérobactéries 11 %, entérocoques 7 %, autres 7 % (DESC 2026). Documentation obtenue dans ≈ 70 % des cas ; principale cause d\'échec : antibiothérapie préalable.<br>Spondylodiscite + bactériémie à S. aureus : rechercher une endocardite.',
 semio:'Rachialgies inflammatoires, fièvre inconstante. <b>Urgence neurologique</b> : déficit, syndrome de la queue de cheval, compression médullaire (épidurite, abcès épidural). Infection du site opératoire précoce (≤ 1 mois) : diagnostic clinique — cicatrice inflammatoire, désunion, écoulement, même sans fièvre.',
 diag:'<b>IRM de tout le rachis</b> (au moins 2 plans orthogonaux pour le niveau atteint ; T1, T2, T1 gadolinium ; 1,5 T si matériel) ; TEP-scanner si IRM contre-indiquée ; scintigraphie, VS et PCT ne sont plus recommandées (<a class="recolink noabbr" href="https://doi.org/10.1016/j.idnow.2023.01.007" target="_blank" rel="noopener">SPILF 2022</a>).<br><b>Hémocultures systématiques</b> (positives dans ≈ 60 %, 40–80 %). Si négatives : <b>ponction-biopsie disco-vertébrale</b> sous scanner ou scopie, après une fenêtre de 14 j sans antibiotique, 3 prélèvements bactériologiques + histologie + mycobactéries/champignons + biologie moléculaire ; à refaire si négative ; priorité abcès > parties molles > disque > os (DESC 2026). Sérologies Coxiella, Bartonella, Whipple si suspicion.<br>Infection du site opératoire : pas d\'antibiotique avant la reprise si le patient est stable ; 5 prélèvements peropératoires, pas d\'écouvillon superficiel.',
 proba:'<b>Pas d\'antibiotique avant la documentation</b>, sauf sepsis ou complication neurologique (<a class="recolink noabbr" href="https://doi.org/10.1016/j.idnow.2023.01.007" target="_blank" rel="noopener">SPILF 2022</a>).<br><b>Situation d\'urgence / post-opératoire non documentée</b> (DESC 2026) : <b>pipéracilline-tazobactam</b> 4 g × 3–4/j ou <b>céfépime</b> 2 g × 3/j <b>+ anti-staphylococcique méti-R</b> : linézolide 600 mg × 2/j, vancomycine 30 mg/kg en charge puis IVSE, teicoplanine (charge 12 mg/kg × 2 puis 12 mg/kg) ou daptomycine 10 mg/kg. Doses du protocole NAR : fiches molécules.',
 doc:'<table class="tbl tx"><tr><th>Germe</th><th>IV</th><th>Relais oral</th></tr><tr><td>SAMS / SCN méti-S</td><td>Céfazoline 80–100 mg/kg/j ou cloxacilline 150 mg/kg/j ; allergie : daptomycine 10 mg/kg ou vancomycine</td><td>Lévofloxacine 500–750 mg + rifampicine 10 mg/kg, ou clindamycine seule (600 mg × 3–4 ou 750 mg × 3)</td></tr><tr><td>SARM / SCN méti-R</td><td>Daptomycine 10 mg/kg ou vancomycine</td><td>Lévofloxacine + rifampicine, clindamycine, ou cotrimoxazole 1600/320 mg × 2</td></tr><tr><td>Streptocoques</td><td>Amoxicilline 150 mg/kg/j ; allergie : daptomycine, vancomycine, teicoplanine</td><td>Amoxicilline 2 g × 3, clindamycine ou lévofloxacine</td></tr><tr><td>Entérocoques</td><td>Amoxicilline 200 mg/kg/j (± gentamicine, ou ceftriaxone) ; E. faecium ou allergie : vancomycine ou daptomycine</td><td>Amoxicilline 2 g × 3 ou linézolide 600 mg × 2</td></tr><tr><td>Entérobactéries</td><td colspan="2">Fluoroquinolone ; ceftriaxone si résistance ou contre-indication</td></tr><tr><td>P. aeruginosa</td><td colspan="2">Avis spécialisé : ceftazidime, aztréonam ou céfépime ± ciprofloxacine</td></tr><tr><td>C. acnes</td><td colspan="2">Amoxicilline ou clindamycine, pas de bithérapie</td></tr></table>Source : schémas <a class="recolink noabbr" href="https://doi.org/10.1016/j.idnow.2023.01.007" target="_blank" rel="noopener">SPILF 2022</a> tels que présentés au DESC 2026 (la place de la gentamicine pour l\'entérocoque y est discordante : vérifier le texte original). Relais oral précoce, voire traitement oral d\'emblée, recommandé (<a class="recolink noabbr" href="https://doi.org/10.1016/j.idnow.2023.01.007" target="_blank" rel="noopener">SPILF 2022</a>).<br><b>Chirurgie</b> : <b>décompression</b> (lavage + laminectomie ± ostéosynthèse) si déficit neurologique ou abcès épidural compressif, classiquement dans les 48 h ; instabilité ; l\'ostéosynthèse n\'est pas contre-indiquée en contexte septique. Abcès épidural non compressif : question ouverte. Avis d\'un chirurgien du rachis pour la stabilité.<br><b>Matériel</b> : infection précoce (≤ 1 mois) → lavage et conservation du matériel ; tardive → ablation et réimplantation en un temps ; ablation si infection de plus de 3 mois.<br>Déficit neurologique non opérable : corticoïdes de sauvetage discutés avec les spécialistes (méthylprednisolone 2 mg/kg 3 j puis décroissance rapide ; extrapolé des épidurites métastatiques, pas de données propres).',
 duree:'<b>6 semaines</b> pour une infection non compliquée, sur rachis natif (essai DTS : 6 semaines non inférieures à 12 — Bernard 2015) ; au moins 1 semaine IV si bactériémie à germe pourvoyeur d\'endocardite.<br>Sur matériel : <b>6 semaines</b> après lavage (précoce) ou après changement en un temps (tardive) (DESC 2026). Pas de traitement au-delà de 6 semaines si l\'infection n\'est pas compliquée (<a class="recolink noabbr" href="https://doi.org/10.1016/j.idnow.2023.01.007" target="_blank" rel="noopener">SPILF 2022</a>).',
 div:'Lever précoce recommandé, décubitus prolongé abandonné ; corset nocturne seulement pour le rachis cervical, pas de corset après ostéosynthèse. Surveillance : CRP ; pas d\'IRM systématique si amélioration ; suivi d\'1 an si matériel.',
 refs:['spilf_idv22','lacasse_desc26','bernard15']},
{id:'volet', cat:'Neurochirurgie', name:'Ostéite du volet crânien et infection de cranioplastie (infection du site opératoire après craniotomie)', site:'os',
 epi:'Infection du volet osseux (autologue ou prothétique) après craniotomie, craniectomie décompressive ou cranioplastie ; souvent associée à un empyème sous- ou extradural (<a href="#p-abces">abcès et empyèmes</a>) ou à une méningite (<a href="#p-ventri">méningite nosocomiale</a>).<br><b>Cohorte lyonnaise</b> (144 ostéites de volet après cranioplastie, 2008–2021) : S. aureus 44,4 %, <b>Cutibacterium acnes 39,6 %</b>, BGN 27,8 %, staphylocoques à coagulase négative 23,6 % ; échec 26,1 % (13,4 % hors surinfections), plus fréquent après craniectomie pour tumeur (Dechaene 2023).',
 semio:'Anomalie de cicatrice dans ≈ 80 % des cas (désunion, écoulement, fistule, collection) ; fièvre inconstante ; formes tardives à C. acnes, peu bruyantes. Rechercher des signes de méningite ou d\'empyème.',
 diag:'Scanner et IRM cérébrale injectés (collection, empyème, atteinte osseuse). <b>Prélèvements peropératoires multiples</b> (os, tissus, matériel ; sonication si possible) ; culture prolongée (C. acnes : garder les cultures ≥ 10 j, IDSA 2017).',
 proba:'Pas de recommandation dédiée. Après prélèvements, couvrir S. aureus (dont SARM selon l\'écologie), C. acnes, staphylocoques à coagulase négative et BGN — par exemple le schéma post-opératoire non documenté des infections du rachis : pipéracilline-tazobactam ou céfépime + linézolide ou vancomycine (extrapolation ; voir <a href="#p-idv">infections rachidiennes</a>). Doses méningées si méningite associée.',
 doc:'Selon la documentation. C. acnes : amoxicilline ou pénicilline G (cf. fiche germe). Staphylocoque sur matériel conservé : bithérapie avec rifampicine si souche sensible (voir <a href="#pharmaco-bio">Anti-biofilm</a>).<br><b>Chirurgie</b> : ablation du volet dans 72,9 % de la cohorte lyonnaise (débridement avec conservation : 22,1 %) ; le curetage des berges osseuses était associé à moins d\'échecs (Dechaene 2023). Cranioplastie différée après guérison.',
 duree:'Non fixée par une recommandation. Durée médiane 12,7 semaines dans la cohorte lyonnaise (Dechaene 2023) ; traitement anti-biofilm prolongé de 6 à 12 semaines proposé par les experts selon l\'ablation ou la conservation du matériel (Conen 2017, 2020).',
 div:'Prise en charge multidisciplinaire (neurochirurgien, infectiologue, microbiologiste), idéalement en centre de référence des infections ostéo-articulaires complexes (CRIOAc).',
 refs:['dechaene23','conen17','conen20','idsa_vent17']},
{id:'tvc_sept', cat:'SNC', name:'Thrombophlébites cérébrales septiques : thrombose septique du sinus caverneux, thrombose otogène du sinus latéral', site:'snc',
 epi:'<b>Sinus caverneux</b> : complication rare et grave d\'une sinusite (ethmoïdale, sphénoïdale surtout), plus rarement d\'une infection otogène, dentaire, pharyngée ou d\'un furoncle de la face ; S. aureus prédominant, puis streptocoques ; anaérobies plus fréquents si origine dentaire (Caranfa 2021). Séquelles neurologiques fréquentes malgré le traitement.<br><b>Sinus latéral / sigmoïde</b> : complication d\'une otite moyenne ou d\'une mastoïdite.',
 semio:'Céphalées, fièvre, puis signes orbitaires (chémosis, exophtalmie, ophtalmoplégie par atteinte des nerfs III, IV, VI, baisse d\'acuité visuelle), souvent bilatéraux ; signes méningés. Thrombose otogène : otalgie, otorrhée, céphalées, hypertension intracrânienne.',
 diag:'Angio-IRM ou angio-scanner cérébral (veineux) : défaut de remplissage du sinus, dilatation de la veine ophtalmique supérieure ; scanner des sinus et des rochers (porte d\'entrée). Hémocultures ; ponction lombaire si signes méningés et absence de contre-indication ; prélèvement de la porte d\'entrée.',
 proba:'Pas de recommandation, pas d\'essai randomisé (Weerasinghe 2016). Antibiothérapie IV à forte dose couvrant S. aureus et les streptocoques : anti-staphylococcique (cloxacilline, ou vancomycine si risque de SARM) + C3G à dose méningée, + métronidazole si origine dentaire ou sinusienne chronique (MSD Manual). Doses : fiches molécules.',
 doc:'Selon les prélèvements. <b>Drainage chirurgical de la porte d\'entrée</b> (sinus, mastoïde, abcès dentaire) : avis ORL ou maxillo-facial urgent.<br><b>Anticoagulation</b> : bénéfice suggéré par les données observationnelles ; <b>corticoïdes</b> : bénéfice incertain (Weerasinghe 2016) — à discuter avec les neurologues et neurochirurgiens.',
 duree:'Non fixée ; prolongée, plus longue si abcès cérébral, empyème ou ostéite associés — à décider avec le référent.',
 div:'Aucune recommandation française ni internationale dédiée ; données issues de séries de cas et de revues.',
 refs:['caranfa21','weerasinghe16','msd_cst']},
{id:'tetanos', cat:'Toxinique', name:'Tétanos', site:'',
 epi:'Toxi-infection à Clostridium tetani (tétanospasmine) après une plaie, parfois minime ou chronique ; non contagieux ; la maladie ne protège pas.<br><b>France</b> (déclaration obligatoire du tétanos généralisé) : 1 à 10 cas par an, 48 cas déclarés entre 2012 et 2021, tous non ou mal vaccinés ; ≈ 71 % chez les 70 ans et plus ; <b>létalité 29 %</b> (35 % après 70 ans, 14 % avant) (Santé publique France).',
 semio:'Trismus, rire sardonique, contractures généralisées (opisthotonos) et spasmes paroxystiques déclenchés par les stimuli, conscience conservée ; laryngospasme ; <b>dysautonomie</b> (instabilité tensionnelle, tachycardie, hyperthermie), principale cause de décès en réanimation. Formes localisées et céphaliques.',
 diag:'<b>Diagnostic clinique</b>. Culture de la plaie peu sensible. Diagnostics différentiels : intoxication (strychnine, neuroleptiques), méningite, hypocalcémie.',
 proba:'<b>Neutraliser la toxine</b> : immunoglobulines humaines antitétaniques IM ; pas de dose standard établie ; dans l\'essai randomisé de Miranda-Filho (2004) : 3 000 UI IM ± 1 000 UI intrathécales (voie intrathécale : meilleur contrôle des spasmes et séjour plus court, sans effet sur la mortalité ; dose intrathécale non établie).<br><b>Antibiotique</b> : <b>métronidazole</b> (bénéfice sur la mortalité contre pénicilline procaïne dans un essai ancien ; la pénicilline est un antagoniste GABA) ; pénicilline G ou doxycycline possibles ; 10 jours dans l\'essai de Ganesh Kumar (2004).<br><b>Plaie</b> : débridement, excision.<br><b>Vaccination</b> : débuter (ou compléter) la vaccination dès le diagnostic, en un site différent des immunoglobulines.',
 doc:'<b>Spasmes</b> : benzodiazépines (diazépam, midazolam ; acidose au propylène glycol si fortes doses de diazépam), sédation profonde, curarisation et ventilation si besoin ; <b>sulfate de magnésium</b> : charge 75–80 mg/kg en 30 min puis 2 g/h (1 g/h après 60 ans), cible 2–4 mmol/L — moins de benzodiazépines et de curares, sans effet sur la survie (essai de Thwaites 2006) ; baclofène intrathécal en réanimation seulement (dépression respiratoire). <b>Dysautonomie</b> : magnésium, morphine, clonidine (données faibles). Environnement calme, nutrition entérale, trachéotomie fréquente (ventilation prolongée).',
 duree:'Antibiotique : 7–10 j (10 j dans les essais). Réanimation souvent prolongée (plusieurs semaines).',
 div:'Données thérapeutiques surtout issues d\'essais de petite taille et de séries (revue de Rodrigo 2014). Maladie à <b>déclaration obligatoire</b> (tétanos généralisé). Prévention après une plaie : voir l\'onglet <a href="#vaccins:v-tetanos">Vaccins</a>.',
 refs:['spf_tet21','rodrigo14','calvac26']},
{id:'botulisme', cat:'Toxinique', name:'Botulisme', site:'',
 epi:'Paralysie par la toxine botulique. En France, forme <b>alimentaire</b> surtout (conserves artisanales, bocaux) ; formes par blessure ou injection de drogue, inhalée (bioterrorisme), du nourrisson, iatrogène (injections de toxine à visée esthétique hors cadre médical). Pas de transmission interhumaine. Létalité 5–10 % (COREB 2024).',
 semio:'Incubation 12–36 h après un repas (jusqu\'à 8 j) ; début brutal, <b>sans fièvre et sans atteinte centrale</b> : troubles digestifs, puis <b>atteinte bilatérale des nerfs crâniens</b> (diplopie, ptosis, troubles de l\'accommodation, mydriase, sécheresse buccale, dysphagie, dysarthrie), puis <b>paralysie flasque descendante symétrique</b> pouvant atteindre les muscles respiratoires (COREB 2024).',
 diag:'Prélèvements <b>avant l\'antitoxine</b> si possible, sans retarder le traitement : sérum et aliment suspect (recherche de toxine), selles (PCR, culture) ; envoi au CNR des bactéries anaérobies et du botulisme (Institut Pasteur, 01 53 55 12 91). ENMG pour le diagnostic différentiel (Guillain-Barré forme Miller Fisher, myasthénie).',
 proba:'<b>Antitoxine botulique équine heptavalente</b> (A à G) : demande d\'<b>autorisation d\'accès compassionnel</b> à l\'ANSM par la pharmacie (plateforme e-Saturne), stock de l\'État géré par Santé publique France, disponible 24 h/24, acheminement en 12 h au plus. <b>Adulte : 1 flacon de 20 mL dilué au 1/10 dans du NaCl 0,9 %, en perfusion IV lente sur 1 h</b> ; prémédication par antihistaminique possible, surveillance d\'une anaphylaxie. À donner tôt, sans attendre la confirmation biologique (COREB 2024).<br>Botulisme par blessure : <b>pénicilline G à forte dose</b> + débridement.<br><b>Aminosides formellement contre-indiqués</b> (aggravation du bloc neuromusculaire).',
 doc:'Surveillance en réanimation ou USC, surveillance neurologique et respiratoire rapprochée (capacité vitale, déglutition) ; ventilation mécanique si atteinte respiratoire ; convalescence de plusieurs mois. Éviter les curares et les médicaments aggravant la transmission neuromusculaire.',
 duree:'Antitoxine : 1 flacon. Antibiotique (forme par blessure) : non fixé par la source.',
 div:'<b>Déclaration obligatoire, signalement immédiat à l\'ARS</b> dès la suspicion (enquête sur la source, rappel d\'aliments) ; agent de la liste MOT et du groupe 2 des agents de bioterrorisme. Précautions standard. Fiche <a class="recolink noabbr" href="https://www.coreb.infectiologie.com/UserFiles/File/procedures/fiche-reb-botulisme-15-11-24.pdf" target="_blank" rel="noopener">COREB 2024</a>.',
 refs:['coreb_botu24','dgs_botu25']},
{id:'empyeme', cat:'Pneumologie', name:'Pleurésie purulente et empyème pleural', site:'pulm',
 epi:'Infection de l\'espace pleural, le plus souvent compliquant une pneumonie (para-pneumonique), plus rarement post-opératoire, post-traumatique ou après ponction/drainage ; flore streptococcique, anaérobies fréquents (souvent non cultivés), S. aureus ; BGN et SARM plus fréquents dans les formes associées aux soins. Pas de recommandation française dédiée : recommandations britanniques BTS 2023 et européennes <a class="recolink noabbr" href="https://doi.org/10.1183/13993003.01062-2022" target="_blank" rel="noopener">ERS/ESTS 2023</a>.',
 semio:'Pneumonie qui ne s\'améliore pas sous antibiotique adapté, fièvre persistante, épanchement croissant ; douleur pleurale.',
 diag:'Échographie pleurale (cloisonnements) et scanner thoracique injecté. <b>Ponction</b> : pus franc, germes à l\'examen direct ou en culture, ou <b>pH ≤ 7,2</b> → drainage (BTS 2023) ; glucose bas, LDH élevés. Culture du liquide en flacons d\'hémoculture, hémocultures. <b>Score RAPID</b> (pronostic, et critère de sélection de l\'essai SLIM) : urée, âge, aspect non purulent, origine associée aux soins, albumine basse — 0–2 risque faible, 3–4 intermédiaire, 5–7 élevé.',
 proba:'Antibiothérapie IV <b>couvrant aérobies et anaérobies</b> selon l\'écologie locale (BTS 2023). En pratique (extrapolation des schémas des pneumonies et des IIA) : <b>amoxicilline-acide clavulanique</b>, ou C3G + métronidazole si communautaire ; associée aux soins : pipéracilline-tazobactam ou céfépime + métronidazole, ± anti-SARM selon les FdR. Pas de macrolide sauf suspicion d\'atypique. Doses : fiches molécules.',
 doc:'Adapter aux cultures, maintenir la couverture des anaérobies même si les cultures sont négatives pour eux.<br><b>Drainage</b> : drain de petit calibre (≤ 14 F) en première intention (BTS 2023). Épanchement résiduel ou cloisonné : <b>fibrinolyse intrapleurale t-PA + DNase</b> (schéma MIST2, le mieux étayé selon <a class="recolink noabbr" href="https://doi.org/10.1183/13993003.01062-2022" target="_blank" rel="noopener">ERS/ESTS 2023</a> : alteplase 10 mg + dornase alfa 5 mg, 2 fois par jour pendant 3 jours — meilleure évacuation, moins de recours à la chirurgie, séjour plus court) (Rahman 2011) ; t-PA seul ou DNase seule inefficaces. <b>Chirurgie (VATS)</b> si échec du drainage et de la fibrinolyse.',
 duree:'<b>Pas de recommandation française.</b> <a class="recolink noabbr" href="https://doi.org/10.1136/thorax-2022-219784" target="_blank" rel="noopener">BTS 2023</a> : en général <b>2 à 6 semaines</b> selon la réponse clinique (des durées plus courtes exposeraient à des rechutes plus précoces) ; aucune étude de puissance suffisante, durée optimale inconnue. <b>Relais oral</b> une fois l\'amélioration clinique obtenue (apyrexie, baisse des marqueurs inflammatoires, amélioration radiologique). L\'usage antérieur, fondé sur l\'avis d\'experts, était d\'au moins 3–4 semaines.<br><b>Essais de raccourcissement</b> (petits effectifs, à confirmer) :<br>• <b>ODAPE</b> (Porcel 2020, double aveugle, arrêté précocement) : épanchements parapneumoniques compliqués <b>communautaires, drainés</b>, <b>stables après 2 semaines</b> d\'amoxicilline-acide clavulanique → arrêt à <b>J14</b> non inférieur à 3 semaines (IV ≈ 6 j en médiane).<br>• <b>SLIM</b> (Hassan 2023, pilote ouvert, monocentrique) : infection pleurale communautaire ou associée aux soins, <b>traitement médical seul</b>, stabilisée en ≤ 14 j, <b>RAPID ≤ 4</b> → <b>14–21 j</b> (médiane 20,5 j) pas plus d\'échecs que 28–42 j.<br><b>En pratique</b> : ≈ <b>2–3 semaines au total</b> envisageables si le patient correspond à ces essais (drainage efficace, stabilité clinique à J14, pas de chirurgie, RAPID ≤ 4). En dehors (chirurgie, RAPID ≥ 5, non stabilisé, collection résiduelle) : <b>pas de donnée</b> → durée plus longue, jusqu\'à 6 semaines selon l\'évolution (<a class="recolink noabbr" href="https://doi.org/10.1136/thorax-2022-219784" target="_blank" rel="noopener">BTS 2023</a>).',
 div:'Durée : seulement deux petits essais (ODAPE, SLIM), synthétisés dans Breathe 2023 (Skouras) ; un essai multicentrique reste nécessaire. Recommandations étrangères uniquement (BTS 2023, <a class="recolink noabbr" href="https://doi.org/10.1183/13993003.01062-2022" target="_blank" rel="noopener">ERS/ESTS 2023</a>).',
 refs:['bts_pleural23','ers_pleural23','mist2_11','odape20','slim23','skouras23']},
{id:'biliaire', cat:'Digestif', name:'Infections biliaires : angiocholite, cholécystite (dont alithiasique de réanimation)', site:'abdo',
 epi:'Infections le plus souvent polymicrobiennes (entérobactéries, entérocoques, anaérobies). <b>Rentabilité des prélèvements</b> (JNI 2017) : culture de bile 59–93 % dans la cholécystite, 29–54 % dans l\'angiocholite ; hémocultures 8–16 % dans la cholécystite, 21–71 % dans l\'angiocholite. Cholécystite alithiasique : patient de réanimation (choc, nutrition parentérale, ventilation prolongée).',
 semio:'Angiocholite : douleur, fièvre, ictère (triade de Charcot), sepsis. Cholécystite : douleur de l\'hypocondre droit, fièvre ; formes gangréneuse ou emphysémateuse (gaz à l\'imagerie).',
 diag:'Échographie abdominale (épaississement pariétal, calcul, dilatation des voies biliaires) ; scanner ou bili-IRM selon le contexte. Hémocultures ; culture de bile lors de tout geste (CPRE, drainage, chirurgie).',
 proba:'Comme les infections intra-abdominales communautaires ou associées aux soins (critères de gravité, FdR de BMR) : voir <a href="#p-iia">Infections intra-abdominales</a>. <b>Contrôle de la source</b> : drainage biliaire (CPRE) pour l\'angiocholite ; cholécystectomie, ou drainage percutané de la vésicule si le patient est trop grave.',
 doc:'Adaptation aux hémocultures et à la culture de bile.',
 duree:'Durées SPILF (évolution favorable, source contrôlée) : <b>angiocholite drainée : 3 j</b> après le drainage (SPILF/GPIP 2021). Cholécystite : opérée non compliquée ≤ 24 h ; vésicule perforée 3 j ; grade III (dysfonction d\'organe) opérée 3 j ; drainage percutané 7 j ; non opérée et non drainée 7 j (SPILF, consultation d\'urgence 2025). Le comité des référentiels SPILF 2020 proposait 5–7 j pour les cholécystites de grade III et les angiocholites si la source est contrôlée.',
 div:'Durées : divergence entre les documents SPILF successifs (2020 : 5–7 j ; 2021 : angiocholite drainée 3 j) — la version la plus récente est retenue. La <a class="recolink noabbr" href="https://sfar.org/prise-en-charge-therapeutique-des-infections-intra-abdominales-de-ladulte/" target="_blank" rel="noopener">RFE SFAR 2026</a> sur les IIA <b>exclut explicitement de son champ</b> les infections biliaires et les abcès hépatiques isolés (chapitre « Champ des RFE ») : les durées SPILF restent la référence.',
 refs:['spilf_durees21','jni_bil17','bua_dig25','spilf_courtes20','sfar_iia26']},
{id:'pancreatite', cat:'Digestif', name:'Pancréatite aiguë nécrosante infectée', site:'abdo',
 epi:'L\'infection de la nécrose est la complication la plus grave de la pancréatite aiguë sévère. Recommandations françaises : SFAR 2021 (avec la SNFGE).',
 semio:'Patient porteur de nécrose pancréatique ou péri-pancréatique qui se dégrade ou ne s\'améliore pas, typiquement après 7 à 10 jours ; sepsis, défaillance d\'organe ; gaz dans la nécrose au scanner.',
 diag:'<b>PCT et scanner</b> plutôt que la CRP pour le diagnostic de nécrose infectée (SFAR 2021, 2+). <b>Ponction à l\'aiguille fine non recommandée</b>, sauf signes de sepsis ou gaz au scanner (avis d\'experts) ; faux négatifs fréquents.',
 proba:'<b>Pas d\'antibioprophylaxie</b> (SFAR 2021, 2−), y compris en cas de nécrose stérile. Nécrose infectée : aucun antibiotique particulier recommandé ; le spectre doit couvrir <b>Enterobacter résistants, E. faecium, P. aeruginosa et levures</b> (SFAR 2021, 2+) — en pratique, molécules d\'une IIA associée aux soins (<a href="#p-iia">IIA</a>) ± antifongique selon la gravité. Adaptation aux prélèvements directs ou aux hémocultures (avis d\'experts).',
 doc:'<b>Drainage plutôt qu\'antibiotiques seuls</b> (2+) ; <b>approche « step-up »</b> par drainage endoscopique ou percutané en premier, nécrosectomie mini-invasive ensuite si besoin (1+) ; drainage d\'autant plus sûr que la collection est organisée (nécrose « walled-off », vers la 4e semaine) ; transfert vers un centre équipé si aucune technique mini-invasive n\'est disponible (avis d\'experts). <b>CPRE urgente seulement en cas d\'angiocholite</b> associée (1+). Nutrition entérale plutôt que parentérale (1+), sonde nasogastrique aussi bien tolérée que naso-jéjunale (1−).',
 duree:'Non fixée par la SFAR 2021 ; prolongée, guidée par le contrôle de la source (drainage, nécrosectomie).',
 div:'Convergence SFAR 2021 / IAP-APA / AGA sur l\'absence de prophylaxie, l\'approche step-up et la nutrition entérale.',
 refs:['sfar_pa21','sfar_pa_comp22']},
{id:'isla', cat:'Digestif', name:'Infection spontanée du liquide d\'ascite (péritonite bactérienne spontanée) du cirrhotique', site:'abdo',
 epi:'Infection du liquide d\'ascite sans foyer intra-abdominal ni perforation. Terrain à risque : protides d\'ascite &lt; 10–15 g/L, hémorragie digestive, insuffisance hépatique sévère (Child-Pugh C) (HAS 2007).<br><b>Données françaises</b> (Piroth 2014) : communautaires — cocci Gram + ≈ 61 % (SCN, entérocoques), BGN ≈ 29 % (E. coli 18 %) ; nosocomiales — cocci Gram + ≈ 67 % (entérocoques 31 %), BGN ≈ 37 % (P. aeruginosa ≈ 6 %), résistance aux quinolones 40–50 %, SARM ≈ 8 % (FMC-HGE 2015).',
 semio:'Fièvre, douleurs abdominales, mais aussi encéphalopathie, insuffisance rénale ou aggravation inexpliquée chez tout cirrhotique ascitique → ponction systématique.',
 diag:'<b>PNN &gt; 250/mm³</b> dans l\'ascite (HAS 2007). Ensemencement de l\'ascite en flacons d\'hémoculture au lit du malade. Bactériascitie : culture positive avec PNN &lt; 250/mm³. Flore polymicrobienne : évoquer une péritonite secondaire (perforation).',
 proba:'<b>Sans attendre les cultures.</b> Communautaire : <b>céfotaxime 1 g × 4/j IV, 5 j</b>, ou amoxicilline-acide clavulanique 1 g × 3/j IV, 7 j ; alternatives : ofloxacine PO (seulement sans choc, encéphalopathie ≥ grade 2, insuffisance rénale ni hémorragie digestive) ou ciprofloxacine IV ; <b>éviter les aminosides</b> (HAS 2007). <b>Nosocomiale</b> (hospitalisation &gt; 48 h, hospitalisation récente, prophylaxie antibiotique, chirurgie récente) : <b>pipéracilline-tazobactam ou carbapénème ± glycopeptide</b> (FMC-HGE 2015, d\'après Jalan 2014). En réanimation : doses fortes (fiches molécules).',
 doc:'<b>Albumine 20 % : 1,5 g/kg à J1 puis 1 g/kg à J3</b> (moins d\'insuffisance rénale et de décès — Sort 1999) (HAS 2007). <b>Ponction de contrôle à 48 h</b> : efficacité si baisse des PNN ≥ 50 % (HAS 2007) ; élargir en cas d\'échec. Relais oral possible après 48 h (amoxicilline-acide clavulanique, ciprofloxacine).',
 duree:'5 j (céfotaxime) à 7 j (autres schémas) (HAS 2007).',
 div:'<b>Prophylaxie</b> : secondaire après un épisode — norfloxacine 400 mg/j au long cours (HAS 2007) ; hémorragie digestive — norfloxacine ou ceftriaxone 1 g/j 7 j. Discuter la transplantation hépatique. La <a class="recolink noabbr" href="https://sfar.org/prise-en-charge-therapeutique-des-infections-intra-abdominales-de-ladulte/" target="_blank" rel="noopener">RFE SFAR 2026</a> sur les IIA exclut de son champ les infections primaires associées à la cirrhose. La synthèse HAS date de 2007 : vérifier les recommandations plus récentes (EASL) pour les infections nosocomiales.',
 refs:['has_cirr07','nousbaum15']},
{id:'ecmo', cat:'Matériel', name:'Infections sous ECMO / assistance circulatoire : infection de canule, bactériémie, PAVM', site:'kt',
 epi:'Patients plus exposés aux infections nosocomiales que les autres patients de réanimation ; la <b>durée de l\'ECMO</b> est le principal facteur de risque ; SCN, Candida, entérobactéries et P. aeruginosa sont les plus fréquents, et les entérobactéries dominent les PAVM sous ECMO (Biffi 2017).<br><b>Infection de canule</b> (Ortuno 2025 : 12 réanimations européennes dont 10 françaises, 109 cas, 2012–2022) : survenue en médiane vers <b>J7</b> (canulation chirurgicale) à <b>J9</b> (percutanée) ; surtout entérobactéries, SCN et entérocoques ; <b>polymicrobienne dans ≈ 40 %</b> (42 épisodes) ; <b>bactériémie au même germe dans 72 %</b> (78/109), dont 41 cas <b>sans signe local</b> ; récidive 13 % (14 patients), <b>la moitié après le retrait de l\'ECMO</b> (médiane 5 j après) ; mortalité en réanimation 51 %, associée à la bactériémie et au choc septique.<br>ECMO veino-veineuse (Marseille) : infection liée au dispositif 9,7 %, colonisation 32 % au retrait (Ann Intensive Care 2017).',
 semio:'Fièvre souvent masquée par l\'échangeur thermique du circuit ; écoulement ou inflammation au point de canulation ; bactériémie sans autre foyer.',
 diag:'Infection de canule retenue (Ortuno 2025) : signes locaux ou généraux + prélèvement positif du point de canulation ; bactériémie si même germe (même antibiogramme) dans les 48 h ; colonisation sans signe local ni bactériémie = pas d\'infection. Hémocultures (sur le patient et sur le circuit selon les pratiques locales) ; prélèvement du point de canulation ; au retrait de l\'ECMO, <b>hémocultures systématiques et culture de l\'extrémité intravasculaire des canules</b> (Ann Intensive Care 2017). Rechercher systématiquement une PAVM et une infection de cathéter associées.',
 proba:'Pas d\'antibioprophylaxie : aucune donnée ne la justifie (Biffi 2017). Infection suspectée : couvrir SCN méti-R (vancomycine, ou daptomycine) + BGN selon l\'écologie et les colonisations (céfépime, pipéracilline-tazobactam ou carbapénème si FdR de BMR) ; voir <a href="#p-bact_kt">Bactériémie liée au cathéter</a> et <a href="#p-pavm">PAVM</a>. Doses : fiches molécules ; STP conseillé (pharmacocinétique modifiée).',
 doc:'Selon l\'antibiogramme ; couvrir tous les germes d\'une infection polymicrobienne. Changement de canule rarement possible : discuter avec l\'équipe d\'assistance (dans Ortuno 2025 : chirurgie du site 29 %, changement de site de canulation 20 % ; ni la durée, ni l\'association d\'antibiotiques, ni le changement de canule n\'étaient associés à la mortalité). Surveiller le point de canulation <b>après le retrait</b> (récidives).',
 duree:'Infection de canule : pas de recommandation. Ortuno 2025 (rétrospectif, 94 patients vivants à J8) : durée médiane 10 j ; <b>≤ 8 j</b> (médiane 7 j) vs &gt; 8 j (médiane 15 j) → récidive et mortalité comparables ; après pondération sur score de propension, &gt; 8 j associé à une mortalité plus élevée (HR 1,72 ; IC95 1,02–2,90), à interpréter avec prudence (facteurs de confusion). Repère issu de cette étude : <b>≤ 8 j</b> si évolution favorable (hors bactériémie à S. aureus ou à Candida). Bactériémie à S. aureus ou à Candida : durées de la fiche bactériémie.',
 div:'Pas de recommandation dédiée ; données observationnelles françaises et européennes.',
 refs:['ortuno25','biffi17','ecmo_vv17']},
{id:'prothvasc', cat:'Matériel', name:'Infection de prothèse vasculaire et d\'endoprothèse aortique', site:'endo',
 epi:'Complication rare et grave des pontages et endoprothèses (aorte, troncs supra-aortiques, membres) ; prothèses ouvertes et endoprothèses considérées comme une même entité (ESVS). Précoce (&lt; 4 mois) ou tardive (&gt; 4 mois).',
 semio:'Fièvre, sepsis, écoulement ou fistule au pli de l\'aine, faux anévrisme, hémorragie ; fistule aorto-digestive (hémorragie digestive, bactériémie polymicrobienne).',
 diag:'<b>Critères MAGIC</b> (cliniques, chirurgicaux, radiologiques, biologiques) recommandés pour confirmer le diagnostic ; <b>3 prélèvements directs</b> pour la microbiologie (ESVS 2020) ; angio-scanner ; TEP-scanner au FDG très bonne valeur prédictive négative, idéalement plus de 4 mois après la chirurgie (faux positifs précoces) (EANM/ESVS 2022).',
 proba:'<b>Antibiothérapie empirique seulement en cas de complication (sepsis, hémorragie) ou si le geste diagnostique est retardé</b> (Delphi ESCMID 2025). Abdominale sans fistule aorto-digestive : couvrir cocci Gram +, BGN et anaérobies, ± SARM/SERM selon le risque ; thoracique sans fistule : priorité aux cocci Gram +, couverture SARM optionnelle (Delphi 2025).',
 doc:'<b>Traitement de référence : explantation complète et reconstruction in situ par matériel autologue</b> (ESVS 2020) ; durée et choix des antibiotiques à décider en équipe multidisciplinaire avec les infectiologues ; surveillance à vie.',
 duree:'Prothèse retirée et remplacée par une veine autologue : <b>6 semaines</b>, relais oral précoce si possible. Matériel prothétique restant : <b>≥ 4–6 semaines IV puis relais oral, total 12 semaines</b> ; plus long si germe virulent, contrôle incomplet de la source ou syndrome inflammatoire persistant (Delphi ESCMID 2025). Traitement conservateur (patient non opérable) : antibiothérapie prolongée, parfois au long cours.',
 div:'Recommandations européennes (ESVS 2020 avec l\'EANM ; nouvelles recommandations ESVS 2025 et consensus Delphi ESCMID 2025). Pas de recommandation française dédiée.',
 refs:['esvs_vgei20','delphi_vgei25','eanm_vgei22']},
{id:'arthrite', cat:'Ostéo-articulaire', name:'Arthrite septique sur articulation native de l\'adulte', site:'os',
 epi:'Recommandations françaises SFR/SPILF/SOFCOT 2020 (diagnostic, principes) et SPILF/GPIP 2023 (choix des antibiotiques). Germes : S. aureus surtout, streptocoques, BGN (sujet âgé, immunodéprimé), gonocoque (sujet jeune). Rechercher la porte d\'entrée (infiltration, ponction, arthroscopie, bactériémie, contiguïté).',
 semio:'Douleur aiguë, impotence, épanchement ; fièvre inconstante. Formes multifocales : rechercher une endocardite.',
 diag:'<b>Ponction articulaire avant tout antibiotique</b> (cytologie, cristaux, Gram, culture en flacons d\'hémoculture, biologie moléculaire) et <b>hémocultures</b> même sans fièvre ; PCT non recommandée. Radiographie systématique (référence), échographie pour guider la ponction. Échographie cardiaque systématique si S. aureus, streptocoque ou entérocoque, même hémocultures négatives (SPILF/GPIP 2023).',
 proba:'<b>Sepsis ou choc sans orientation</b> : céfazoline ou cloxacilline (allergie : daptomycine, ou vancomycine, teicoplanine) <b>+ amikacine 24–48 h</b>, puis adaptation au Gram et aux cultures. Liquide purulent avec examen direct négatif : céfazoline ou cloxacilline, élargie si l\'histoire le justifie (SPILF/GPIP 2023). Sinon, attendre le résultat de la ponction. Doses : fiches molécules (doses fortes, bonne diffusion osseuse).',
 doc:'<table class="tbl tx"><tr><th>Germe</th><th>IV initial</th><th>Relais oral</th><th>Durée</th></tr><tr><td>SAMS</td><td>Céfazoline, cloxacilline ; allergie : daptomycine (ou vancomycine, teicoplanine)</td><td>Selon l\'antibiogramme : clindamycine (si sensible), doxycycline, linézolide, cotrimoxazole ; pas de lévofloxacine ni de rifampicine en monothérapie</td><td>6 sem</td></tr><tr><td>SARM</td><td>Daptomycine (ou vancomycine, teicoplanine)</td><td>Idem</td><td>6 sem</td></tr><tr><td>Streptocoques</td><td>Amoxicilline ; allergie non grave : céfazoline ou C3G ; grave : daptomycine</td><td>Amoxicilline ; clindamycine, linézolide</td><td>4 sem</td></tr><tr><td>Entérocoques</td><td>Amoxicilline ; résistance ou allergie : vancomycine, teicoplanine</td><td>Amoxicilline, linézolide</td><td>4 sem</td></tr><tr><td>Gonocoque</td><td colspan="2">Céfotaxime ou ceftriaxone (alternative : FQ)</td><td>7 j</td></tr><tr><td>Entérobactéries</td><td>Céfotaxime, ceftriaxone ; groupes 3–4 : céfépime ; BLSE : carbapénème</td><td>Lévofloxacine</td><td>6 sem</td></tr><tr><td>P. aeruginosa</td><td>Ceftazidime ou céfépime (sinon pip-tazo, carbapénème)</td><td>Ciprofloxacine si S</td><td>6 sem</td></tr></table>Source : SPILF/GPIP 2023 (doses : texte complet). Monothérapie habituellement suffisante ; <b>relais oral rapide</b> si évolution favorable et hémocultures négatives. <b>Drainage articulaire</b> (ponctions itératives, lavage arthroscopique ou arthrotomie) : avis orthopédique (SFR/SPILF/SOFCOT 2020).',
 duree:'Durées SPILF/GPIP 2023 (voir le tableau) : 7 j (gonocoque), 4 semaines (streptocoque, entérocoque, C. acnes), 6 semaines (staphylocoques, BGN, P. aeruginosa) ; main et poignet : 2 semaines sans ostéolyse, 4 semaines avec.',
 div:'Prothèse articulaire : relève de la prise en charge des infections sur matériel, avec avis d\'un centre de référence (CRIOAc).',
 refs:['spilf_arthr23','sfr_arthr20']},
{id:'palu', cat:'Importé', name:'Paludisme grave d\'importation de l\'adulte', site:'',
 epi:'France : environ 5 000 cas importés par an, dont environ 350 graves ; létalité 0,4 % au total et 2,9 % dans les formes graves (DESC 2024, d\'après les recommandations <a class="recolink noabbr" href="https://www.infectiologie.com/fr/recommandations.html" target="_blank" rel="noopener">SPILF 2017</a>). P. falciparum surtout ; P. vivax et P. knowlesi peuvent aussi donner des formes graves.',
 semio:'Toute fièvre au retour d\'une zone d\'endémie, même sous chimioprophylaxie. <b>Critères de réanimation</b> : coma, convulsions répétées, défaillance respiratoire ou circulatoire (choc, souvent septique), acidose métabolique ou hyperlactatémie, hémorragie grave, insuffisance rénale nécessitant une épuration, parasitémie &gt; 15 %. <b>USC</b> : confusion simple, convulsion isolée, saignement mineur, ictère isolé, parasitémie &gt; 4 %, insuffisance rénale modérée, anémie isolée bien tolérée (DESC 2024).',
 diag:'Frottis sanguin et goutte épaisse (ou test moléculaire) en urgence, avec la parasitémie ; à refaire 12–24 h plus tard si négatif et suspicion persistante. Hémocultures systématiques. Bilan de gravité : lactates, pH, glycémie, bilirubine, créatinine, hémoglobine, plaquettes.',
 proba:'<b>Artésunate IV</b> (traitement de référence, supérieur à la quinine) : <b>2,4 mg/kg à H0, H12, H24, H48 puis toutes les 24 h</b>, jusqu\'à 9 doses (7 j) ; pas d\'adaptation hépatique ou rénale ; ECG conseillé. <b>Relais oral obligatoire</b> par une combinaison à base d\'artémisinine (dihydroartémisinine-pipéraquine, artéméther-luméfantrine) ou atovaquone-proguanil dès disparition des critères de gravité, en moyenne après 3–4 doses IV. Quinine IV seulement si l\'artésunate n\'est pas disponible (relais par artésunate dans les 24 h). Retour d\'une zone de résistance à l\'artémisinine : artésunate + quinine (DESC 2024).<br><b>Co-infection bactérienne suspectée</b> (BGN classiquement) : céfépime, pipéracilline-tazobactam ou carbapénème + amikacine (DESC 2024).',
 doc:'<b>Exsanguino-transfusion non recommandée</b>. Grossesse : artésunate IV quel que soit le terme. Formes graves non falciparum : artésunate IV.',
 duree:'Artésunate : jusqu\'à 7 j IV ou relais oral complet. <b>Surveillance de l\'hémolyse retardée post-artésunate</b> (J7–J30, environ 15 % des cas, transfusion chez la moitié d\'entre eux) : bilan d\'hémolyse à J3, J7, J14, J21, J28 (DESC 2024).',
 div:'Recommandations françaises : <a class="recolink noabbr" href="https://www.infectiologie.com/fr/recommandations.html" target="_blank" rel="noopener">SPILF 2017</a> (mise à jour des RPC 2007), synthétisées au <a class="recolink noabbr" href="https://www.infectiologie.com/UserFiles/File/formation/desc/2024/seminaire-mars-2024/t-24-vend-29-mars/conf-3-paludisme-d-importation.pdf" target="_blank" rel="noopener">DESC 2024</a>.',
 refs:['spilf_palu17','desc_palu24']},
{id:'tb_grave', cat:'Mycobactéries', name:'Tuberculose grave en réanimation : méningite tuberculeuse, miliaire', site:'snc',
 epi:'Neuro-tuberculose : mortalité 25–50 %, liée à la gravité initiale (Thwaites 2004) (DESC 2026). Recommandations françaises : SPILF/SPLF (tuberculose et neuro-tuberculose).',
 semio:'Méningite subaiguë (fièvre, céphalées, troubles de conscience), atteinte des nerfs crâniens, hydrocéphalie, vascularite (infarctus) ; LCS lymphocytaire, hyperprotéinorachie, hypoglycorachie. Miliaire : fièvre prolongée, hypoxémie, atteinte multiviscérale.',
 diag:'LCS : examen direct, culture et PCR M. tuberculosis (volume important, ponctions répétées) ; imagerie cérébrale systématique ; recherche d\'autres localisations (crachats, tubages, urines, biopsies) ; sérologie VIH.',
 proba:'<b>Quadrithérapie</b> RHZE : isoniazide 5 mg/kg/j, rifampicine 10 mg/kg/j, éthambutol 20 mg/kg/j, pyrazinamide 25 mg/kg/j (DESC 2026) ; débuter <b>par voie IV</b> en cas de neuro-tuberculose, avec dosages pharmacologiques. Régimes intensifiés (rifampicine forte dose, fluoroquinolone) : pas de bénéfice démontré, voire délétères (Heemskerk 2016 ; DESC 2026).<br><b>Dexaméthasone</b> dans la méningite tuberculeuse (schéma de Thwaites 2004 : 0,4 mg/kg/j IV la 1re semaine en cas de forme grave, puis décroissance sur 6–8 semaines), conseillée aussi chez les patients vivant avec le VIH (DESC 2026). Miliaire avec hypoxémie : corticoïdes discutés.',
 doc:'Adaptation à l\'antibiogramme (résistance à l\'isoniazide ou à la rifampicine : avis spécialisé). Hydrocéphalie : dérivation (DVE puis DVP). Isolement air au moins 14 jours après le début du traitement, jusqu\'à 30 jours dans certains cas (SF2H, d\'après le DESC 2026).',
 duree:'Neuro-tuberculose : <b>9 à 12 mois</b> (2 mois de quadrithérapie, puis bithérapie) (DESC 2026). Tuberculose pulmonaire sensible : 6 mois (2 RHZE / 4 RH).',
 div:'Interactions de la rifampicine (puissant inducteur : nimodipine contre-indiquée, antiépileptiques, voriconazole…) : voir <a href="#pharmaco-tox:interneuro">Toxicités → interactions</a>.',
 refs:['tattevin_desc26','thwaites04','heemskerk16']},
{id:'lepto', cat:'Zoonose', name:'Leptospirose grave (maladie de Weil)', site:'',
 epi:'Zoonose (contact avec l\'eau douce ou les urines de rongeurs, activités agricoles, baignade). <b>France 2024</b> : 886 cas (441 dans l\'Hexagone, surtout l\'ouest et la Corse, 445 dans les DROM), 653 hospitalisés (74 %), dont plus de la moitié en réanimation, 13 décès (Santé publique France, d\'après La Revue du praticien). Inscrite récemment sur la liste des maladies à signalement obligatoire.',
 semio:'Fièvre brutale, myalgies, suffusion conjonctivale, puis 4 à 9 jours après les premiers signes : ictère, insuffisance rénale aiguë, hémorragies, atteinte pulmonaire (hémorragie intra-alvéolaire), méningite, défaillance multiviscérale ; rhabdomyolyse.',
 diag:'PCR dans le sang (et les urines) dès les premiers jours ; sérologie (IgM après J7) ; CNR de la leptospirose.',
 proba:'<b>Formes graves : β-lactamine IV</b> — pénicilline G, ampicilline (amoxicilline), ceftriaxone ou céfotaxime ; doxycycline dans les formes non graves ou en cas d\'allergie (SFM 2025 ; La Revue du praticien). Traitement le plus précoce possible.',
 doc:'Réanimation : épuration extra-rénale, ventilation protectrice (hémorragie alvéolaire), transfusion si besoin.',
 duree:'<b>10 jours</b> (La Revue du praticien) ; 7 à 10 jours selon les sources.',
 div:'Maladie à signalement obligatoire (MSO) ; vaccination de certains professionnels exposés (sérogroupe Icterohaemorrhagiae).',
 refs:['revprat_lepto','sfm_lepto25','spf_lepto26']},
{id:'herpes_rea', cat:'Virus', name:'Réactivations HSV et CMV chez le patient de réanimation non immunodéprimé ; VZV disséminé', site:'',
 epi:'<b>HSV</b> : réactivation oropharyngée chez 20–50 % des patients de réanimation après 3–5 j de ventilation ; détection dans les voies aériennes distales chez 20–64 % après 7 j. <b>CMV</b> : réactivation sanguine chez ≈ 30 % des patients séropositifs, après 4 à 12 j de réanimation (Luyt, JNI 2022). Associées à une surmortalité, sans lien causal démontré.',
 semio:'Le plus souvent asymptomatiques ; bronchopneumonie herpétique possible (lésions labiales, réactivation oropharyngée) ; CMV : fièvre inexpliquée, cytopénies, hépatite, colite, pneumonie (diagnostic difficile).',
 diag:'PCR HSV (gorge, LBA), PCR CMV quantitative dans le sang ; la pneumonie à HSV ou CMV vraie suppose une atteinte cytologique ou histologique, rarement obtenue (Luyt 2012).',
 proba:'<b>Pas de traitement préemptif systématique</b> :<br>• HSV : aciclovir IV 5 mg/kg × 3/j pendant 14 j <b>n\'augmente pas le nombre de jours sans ventilation</b> (essai PTH, 238 patients ventilés ≥ 96 h avec réactivation oropharyngée ; mortalité à J60 22 % contre 33 %, différence non significative) (Luyt 2020).<br>• CMV : la prophylaxie par ganciclovir réduit les réactivations mais ne modifie ni l\'IL-6 ni la mortalité ; non recommandée en routine (Limaye 2017).<br>Traitement à discuter au cas par cas : atteinte d\'organe documentée, réactivation CMV à forte charge, absence d\'autre explication.',
 doc:'<b>VZV disséminé</b> (zona étendu ou viscéral, varicelle grave de l\'adulte) : <b>aciclovir IV</b> à dose d\'encéphalite (voir <a href="#p-enceph">Encéphalites</a> et la fiche aciclovir), isolement air et contact. Immunodéprimé : voir <a href="#p-immunodep">Patient immunodéprimé</a>.',
 duree:'Non fixée en dehors des atteintes d\'organe (HSV : 14 j dans l\'essai PTH ; CMV : selon la charge virale et l\'atteinte).',
 div:'Aucune recommandation ; deux essais randomisés négatifs (PTH en France, Limaye aux États-Unis).',
 refs:['luyt_pth20','limaye17','luyt_jni22','luyt_rea12']},
{id:'thrombo', cat:'Bactériémies', name:'Thromboses septiques : thrombophlébite suppurée sur cathéter, syndrome de Lemierre', site:'bact',
 epi:'<b>Thrombophlébite suppurée</b> : thrombose infectée d\'une veine cathétérisée (périphérique ou centrale), complication d\'une bactériémie liée au cathéter (S. aureus, BGN, Candida).<br><b>Syndrome de Lemierre</b> : thrombose des veines de la tête et du cou (jugulaire interne surtout) avec emboles septiques, après une infection oropharyngée ; sujet jeune (âge médian 21 ans dans une série de 712 cas) ; Fusobacterium necrophorum est le germe classique.',
 semio:'À évoquer devant une bactériémie ou fongémie qui persiste malgré un traitement adapté et le retrait du cathéter, sans autre source. Lemierre : angine ou infection cervicale, puis sepsis, douleur/œdème cervical, emboles pulmonaires (nodules excavés).',
 diag:'Écho-doppler veineux ; angio-TDM cervico-thoracique (Lemierre : thrombose jugulaire, emboles septiques) ; hémocultures répétées jusqu\'à négativation. Lemierre avec atteinte intracrânienne : IRM/angio-IRM (risque évolutif plus élevé).',
 proba:'Retrait du cathéter. Antibiothérapie selon le germe (cf. fiche Bactériémie liée au cathéter). Lemierre : amoxicilline-acide clavulanique, ou C3G + métronidazole (cf. Abcès pulmonaire).',
 doc:'Adaptation à l\'antibiogramme. Anticoagulation : voir « Mesures associées » (pas de recommandation consensuelle).',
 duree:'Thrombophlébite suppurée sur cathéter : <b>au moins 3–4 semaines</b> (IDSA 2009, B-III).',
 div:'Aucune recommandation française. IDSA 2009 : rôle de l\'héparine non établi. Lemierre : données observationnelles uniquement.',
 refs:['idsa_crbsi09','splf_mtev19','valerio21','adedeji21']},
{id:'choc', cat:'Sepsis', name:'Sepsis / choc septique sans point d\'appel', site:'bact',
 epi:'—',
 semio:'Sepsis-3 : dysfonction d\'organe (SOFA ≥ 2) ; choc : vasopresseurs pour PAM ≥ 65 + lactate > 2 mmol/L.',
 diag:'2 paires d\'hémocultures (40–60 mL) avant antibiotiques sans retarder ; prélèvements orientés ; lactate.',
 proba:'Antibiothérapie dans l\'heure (choc). Communautaire : C3G + amikacine (± anti-anaérobie selon point d\'appel). Associée aux soins : β-lactamine anti-Pseudomonas (pip-tazo/céfépime) + amikacine ; carbapénème si colonisation BLSE < 3 mois (HAS 2019) ; ± anti-SARM selon FdR. Première dose pleine sans adaptation rénale ; pas de réduction de dose des β-lactamines les 24 premières heures (SFAR/SFPT 2019) ; perfusion prolongée/continue après dose de charge.',
 doc:'Réévaluation à 48–72 h obligatoire (désescalade, arrêt si non infectieux).',
 duree:'Selon foyer et germe (cf. fiches) ; 7 j pour la plupart des bactériémies à BGN non compliquées.',
 div:'Doses de β-lactamines : les tableaux CA-SFM/SPILF visent 100 % fT > CMI ; la SFAR/SFPT (2019) vise fC 4–8 × CMI chez le patient de réanimation → l\'app privilégie la cible SFAR (fortes posologies, perfusion prolongée/continue, STP) et le signale.',
 refs:['ssc21','has_carba19','sfar_bl2019','doses25']},
{id:'abces_pulm', cat:'Respiratoire', name:'Abcès pulmonaire / pneumonie nécrosante', site:'pulm',
 epi:'Cavité nécrotique (> 2 cm, souvent avec niveau hydro-aérique). <b>Primitif</b> : inhalation (troubles de conscience — neuroréanimation ++, alcool, troubles de déglutition, mauvais état dentaire). <b>Secondaire</b> : obstacle bronchique (cancer, corps étranger), emboles septiques (endocardite tricuspide, thrombophlébite jugulaire de Lemierre, cathéter), immunodépression, surinfection de cavité préexistante.<br><b>Germes les plus fréquents</b> : anaérobies (Prevotella, Fusobacterium, Peptostreptococcus, Bacteroides) souvent en flore mixte avec streptocoques du groupe milleri (S. anginosus) ; <b>Klebsiella pneumoniae</b> (souches hypervirulentes — diabète, alcool, origine asiatique ; rechercher d\'autres foyers : foie, œil, SNC) ; <b>S. aureus</b> (dont souches productrices de leucocidine de Panton-Valentine (PVL) chez le sujet jeune, post-grippal ; emboles septiques) ; P. aeruginosa et entérobactéries multirésistantes (nosocomial) ; plus rares : Nocardia, Actinomyces, Rhodococcus, mycobactéries (tuberculose ++), Aspergillus/Mucorales (immunodéprimé), amibe (rupture d\'abcès hépatique).',
 semio:'Fièvre prolongée, expectoration purulente parfois fétide (anaérobies), vomique, hémoptysie, altération de l\'état général ; tableau suraigu (fièvre élevée, hémoptysies, leucopénie, choc) évocateur de pneumonie nécrosante à S. aureus PVL+.',
 diag:'TDM thoracique injecté (diagnostic, empyème, différentiel avec cancer excavé, bulles infectées). Hémocultures. Prélèvements respiratoires profonds (aspiration, fibroscopie avec prélèvement protégé/LBA — recherche aussi d\'obstacle endobronchique). <b>Recherche de BK systématique</b> (3 examens + PCR ; isolement air jusqu\'au résultat). Cultures anaérobies prolongées, recherche de Nocardia/Actinomyces à signaler au labo. Ponction scanno-guidée si échec. Sérologie VIH. <b>Recherche de la toxine PVL</b> (PCR des gènes lukS/lukF-PV sur la souche, CNR des staphylocoques, Lyon) si S. aureus et : pneumonie nécrosante ou abcès multiples, sujet jeune sans comorbidité, hémoptysies, leucopénie, syndrome grippal préalable, infections cutanées récurrentes (furoncles) chez le patient ou l\'entourage — sans attendre le résultat pour débuter un antitoxinique si forte suspicion.',
 proba:'<b>Communautaire / inhalation</b> : amoxicilline-acide clavulanique (forte posologie) ; alternative : C3G + métronidazole ; allergie : clindamycine (ou moxifloxacine). La SPILF 2025 ne recommande plus le métronidazole systématique dans la pneumonie d\'inhalation simple, mais la couverture anaérobie reste justifiée en cas d\'abcès. <b>Associé aux soins / FdR de BMR</b> : pipéracilline-tazobactam (± amikacine si choc) ; carbapénème selon colonisation BLSE (HAS 2019). <b>Suspicion de S. aureus PVL</b> (tableau suraigu, nécrose, leucopénie) : β-lactamine anti-staphylococcique (ou vancomycine si SARM suspect) <b>+ antitoxinique : linézolide (préféré, actif sur SARM) ou clindamycine</b> ; IgIV discutées dans les formes graves (avis d\'expert). Lemierre : amox-clav ou C3G + métronidazole, anticoagulation discutée.',
 doc:'Adaptation à la documentation ; SAMS PVL+ : cloxacilline + linézolide/clindamycine ; SARM PVL+ : linézolide (seul ou + vancomycine). Klebsiella hypervirulente : C3G si S, chercher et drainer les autres foyers. <b>Drainage</b> : percutané/endoscopique si abcès volumineux (> 6 cm), sepsis persistant après 7–10 j d\'antibiothérapie adaptée, absence de communication bronchique ; chirurgie si hémoptysie grave, échec, nécrose étendue ; drainage de tout empyème associé.',
 duree:'Pas de durée consensuelle : classiquement <b>3 à 6 semaines</b>, guidée par l\'évolution clinique et radiologique (relais oral possible après apyrexie) ; la SPILF/SPLF 2025 réserve les durées > 7 j des PAC aux complications comme l\'abcès. Durée de l\'antitoxinique non établie (≥ 7 j / phase aiguë ; limiter le linézolide à ≤ 28 j).',
 div:'Pas de recommandation française dédiée à l\'abcès pulmonaire ; synthèse des recommandations PAC/inhalation (SPILF 2025), des données du CNR des staphylocoques et de mises au point (JNI).',
 refs:['spilf_pac25','spilf_inhal25','lorut_jni18','luyt_jni20','dumitrescu07','has_carba19']},
{id:'immunodep', cat:'Sepsis', name:'Choc septique du patient immunodéprimé (neutropénie, greffe, hémopathie, biothérapies)', site:'bact',
 epi:'<b>Neutropénie (< 0,5 G/L)</b> : BGN dont P. aeruginosa et entérobactéries BLSE (colonisation), streptocoques oraux (mucite), SCN/S. aureus (cathéter), C. septicum (typhlite) ; fongique si neutropénie prolongée (Candida, Aspergillus). <b>Greffe d\'organe/CSH, corticothérapie, biothérapies</b> : + Listeria, Nocardia, Legionella, pneumocystose, CMV/HSV/adénovirus, Aspergillus/Mucorales, tuberculose, strongyloïdose disséminée (hyperinfection — originaires de zones d\'endémie sous corticoïdes). <b>Asplénie</b> : pneumocoque, méningocoque, H. influenzae, Capnocytophaga (morsure de chien) — purpura fulminans. <b>VIH (CD4 < 200)</b> : pneumocystose, tuberculose, cryptococcose, toxoplasmose.',
 semio:'Signes inflammatoires atténués (neutropénie, corticoïdes) ; fièvre parfois seul signe ; dégradation rapide.',
 diag:'Hémocultures sur cathéter et périphérie (avant antibiotiques), ECBU, prélèvements orientés, TDM thoracique précoce (± sinus/abdomen), LBA précoce si pneumopathie (bactéries, PCR Pneumocystis, galactomannane, virus, mycobactéries), β-D-glucane et galactomannane sériques, PCR CMV sang, antigène cryptococcique, sérologie/examen des selles anguillulose si exposition.',
 proba:'<b>Neutropénie + choc (ECIL-4, stratégie de désescalade)</b> : β-lactamine anti-Pseudomonas à forte posologie (pip-tazo ou céfépime) <b>+ amikacine</b> ; <b>carbapénème</b> si colonisation/infection BLSE < 3 mois (HAS 2019 : carbapénème non recommandé en aplasie fébrile en dehors de ce cas) ; <b>+ vancomycine</b> (ou autre anti-Gram +) si instabilité hémodynamique, suspicion d\'infection de cathéter, de peau/tissus mous, pneumonie, colonisation SARM, mucite sévère sous FQ prophylactique. <b>Antifongique</b> : échinocandine si choc avec FdR de candidose (colonisation, KT, nutrition parentérale) ; antifongique actif sur Aspergillus (voriconazole/isavuconazole ou amphotéricine B liposomale) si signes évocateurs (TDM, GM). <b>Greffé/corticothérapie</b> : selon foyer + amoxicilline si méningite/encéphalite (Listeria) ; cotrimoxazole forte dose si pneumocystose suspectée (+ corticoïdes selon contexte) ; ivermectine si risque d\'anguillulose. <b>Asplénie</b> : C3G forte dose (± vancomycine si méningite et pneumocoque à risque).',
 doc:'Réévaluation à 48–72 h : désescalade selon documentation ; arrêt possible des antibiotiques empiriques après 72 h si apyrexie ≥ 48 h, stabilité et absence de documentation (ECIL-4), même en neutropénie persistante.',
 duree:'Selon le foyer et le germe (cf. fiches) ; pneumocystose 21 j ; candidémie 14 j après hémocultures négatives et sortie d\'aplasie.',
 div:'HAS 2019 (carbapénèmes réservés au choc + colonisation BLSE) et ECIL-4 (désescalade en cas de choc) sont concordantes ; pas de RFE SFAR/SRLF spécifique.',
 refs:['ecil4','has_carba19','ecil5pjp','escmid_asp18','ecmm_cand25','ssc21']},
{id:'sinusite', cat:'ORL', name:'Sinusite nosocomiale du patient de réanimation (sondes nasales, intubation) — soins de nez, DRP, ponction-drainage, indications des antibiotiques', site:'pulm', epi:'<b>Cette fiche concerne la sinusite acquise en réanimation</b> chez un patient admis pour une autre raison (sondes nasales, intubation). La sinusite communautaire compliquée qui motive l\'admission (cellulite orbitaire, empyème, abcès cérébral, méningite, thrombophlébite) relève des fiches Méningite et Abcès cérébral : drainage ORL/neurochirurgical urgent et antibiothérapie IV systématique.<br>Complication de l\'intubation et de la ventilation prolongées, souvent sous-estimée car pauvre en signes : sinusite infectieuse chez ≈ <b>20–30 % des patients intubés ≥ 7 j</b> (les opacités radiologiques non infectieuses sont plus fréquentes). <b>FdR</b> : <b>intubation nasotrachéale</b> (≫ orotrachéale), <b>sonde nasogastrique</b>, <b>traumatisme crânien/facial</b>, décubitus, sédation, méchage nasal. <b>Germes</b> : BGN (<b>P. aeruginosa, A. baumannii, entérobactéries</b>), <b>S. aureus</b>, levures ; souvent polymicrobien, mêmes germes que les PAVM. Le sinus est un réservoir qui peut ensemencer l\'arbre trachéobronchique : association avec les PAVM.', semio:'Fièvre inexpliquée (« fièvre sans foyer » du patient intubé), rhinorrhée purulente ou pus au méat moyen (inconstants). Complications : PAVM, méningite, abcès cérébral, cellulite orbitaire, thrombophlébite du sinus caverneux. Sinusite <b>fongique invasive</b> (Mucorales, Aspergillus) chez le diabétique en acidocétose/immunodéprimé : nécrose noirâtre des cornets/palais → <b>urgence ORL</b> (biopsie, débridement).', diag:'<b>TDM des sinus sans injection</b> (référence) : niveau hydro-aérique ou opacité complète d\'un sinus maxillaire, ± sphénoïde/ethmoïde ; la radiographie est insuffisante ; l\'échographie des sinus maxillaires au lit peut orienter. <b>Confirmation microbiologique par ponction-aspiration du sinus maxillaire</b> (ORL, voie endonasale par le méat inférieur ou voie canine) : liquide purulent et <b>culture ≥ 10³ UFC/mL</b> ; examen direct (levures). Un écouvillon nasal n\'a qu\'une valeur diagnostique faible (concordance ≈ 63 % avec la ponction), à réserver aux contre-indications de la ponction. La présence de pus au méat moyen en endoscopie, associée à une atteinte au scanner, prédit bien une ponction positive. <b>Sinus sphénoïdal</b> : ponction difficile (endoscopie, opérateur entraîné), réservée à la sphénoïdite isolée dans un contexte infectieux. Dans l\'essai randomisé de Holzapfel 1999 (intubés nasotrachéaux), la recherche systématique par TDM des sinusites fébriles, traitées par lavage et antibiotiques IV, s\'accompagnait de moins de PAVM ; l\'effet sur la mortalité restait à confirmer.', proba:'<b>1. Supprimer les sondes nasales</b> (mesure essentielle)<br>• Intubation <b>orotrachéale</b>, sonde <b>orogastrique</b> ; proclive 30–45°.<br><b>2. Soins de nez / DRP (désobstruction rhinopharyngée)</b><br>• Solution : <b>NaCl 0,9 % (ou eau de mer isotonique)</b>, 10–20 mL par narine à la seringue, 3–4 fois/j, tête tournée sur le côté, puis aspiration douce ; les lavages à grand volume et faible pression sont les plus efficaces.<br>• Vasoconstricteur nasal de courte durée (≤ 5 j) à discuter, <b>à éviter en neuroréanimation</b> (HTIC, vasospasme, HTA non contrôlée).<br><b>3. Et la chlorhexidine (ou la povidone iodée) ?</b><br>• <b>Pas de chlorhexidine en lavage nasal ou sinusien</b> : aucune donnée dans la sinusite nosocomiale, toxicité ciliaire et irritation muqueuse, risque allergique (anaphylaxie) et neurotoxicité en cas de brèche ostéoméningée. La chlorhexidine reste réservée à la peau, au bain de bouche (soins de bouche) et à la décolonisation pré-opératoire (avec la mupirocine nasale).<br>• Povidone iodée diluée : étudiée seulement dans la rhinosinusite chronique ambulatoire ; non validée en réanimation.<br>• Lavages par le drain avec des solutions « antibio-corticoïdes » : pratique ORL ancienne, sans preuve ; à réserver à un protocole ORL local.<br><b>4. Ponction-drainage du sinus maxillaire (ORL) — indications</b><br>• <b>Diagnostique</b> : fièvre ou sepsis <b>sans autre foyer</b> chez un patient intubé avec atteinte sinusienne au scanner (niveau hydro-aérique ou opacité complète) ; patient <b>immunodéprimé</b> ou <b>suspicion de sinusite fongique</b> (biopsie).<br>• <b>Thérapeutique</b> : <b>persistance de la fièvre 48–72 h après retrait des sondes nasales et soins de nez</b> ; <b>sinus « bloqué »</b> (opacité complète sans drainage naturel) ; échec d\'une antibiothérapie adaptée ; sinusite associée à une PAVM récidivante au même germe.<br>• Technique : ponction au trocart par le méat inférieur après anesthésie locale, aspiration pour culture (≥ 10³ UFC/mL), lavage au NaCl 0,9 % jusqu\'à retour clair ; si pus : <b>drain intrasinusien</b> (type Albertini) laissé quelques jours pour des <b>lavages pluriquotidiens</b> au NaCl 0,9 % (ex. 20 mL 2–3 fois/j) jusqu\'à retour clair et apyrexie.<br>• <b>Drainage chirurgical</b> (méatotomie moyenne endoscopique) : échec du drainage, récidive, sinusite frontale/ethmoïdale compliquée, <b>complications orbitaires ou intracrâniennes</b> (urgence), sinusite fongique invasive (débridement).<br>• <b>Sphénoïde</b> : ponction sous endoscopie réservée à la sphénoïdite <b>isolée</b> dans un contexte infectieux.<br><b>5. Antibiotiques : quand ?</b><br>• <b>Aucune recommandation</b> (ni française, ni européenne) ne définit les indications d\'antibiothérapie de la sinusite nosocomiale. Dans les essais de Rouby (1994) et Holzapfel (1999), les sinusites infectieuses <i>confirmées par ponction</i> étaient traitées par drainage + antibiotiques IV ; la stratégie « lavages seuls » n\'a pas été comparée dans un essai.<br>• <b>Lavages / DRP seuls (pratique du service)</b> : opacité ou niveau sinusien chez un patient sans sepsis, stable, avec un autre foyer exclu ou traité → retrait des sondes nasales, DRP, réévaluation à 48–72 h.<br>• <b>Situations où une règle générale impose un anti-infectieux</b> :<br>• Sepsis ou choc septique sans autre foyer → antibiothérapie probabiliste immédiate (SSC 2021), puis adaptation au liquide de ponction.<br>• PAVM associée → le traitement de la PAVM (SFAR/SRLF 2017) couvre la sinusite si le germe est le même.<br>• Complication orbitaire ou endocrânienne (cellulite orbitaire, méningite, empyème, abcès, thrombophlébite du sinus caverneux) → antibiothérapie IV + drainage urgent (cf. fiches Méningite et Abcès cérébral).<br>• Immunodéprimé ou suspicion de sinusite fongique invasive → biopsie, débridement et antifongique (cf. Mucormycose).<br>• <b>Zone grise, au cas par cas</b> : fièvre persistante malgré retrait des sondes et drainage, avec liquide de ponction purulent et culture ≥ 10³ UFC/mL.<br>• Choix probabiliste : couvrir <b>P. aeruginosa et S. aureus</b> selon l\'écologie et la colonisation (comme une PAVM tardive), puis adapter à la culture.<br><b>⚠ Neuroréanimation</b><br>• Après chirurgie trans-sphénoïdale ou de la base du crâne, ou fracture de la base avec brèche ostéoméningée : <b>pas de sonde nasale, pas de lavage sous pression, pas de ponction</b> sans accord neurochirurgical/ORL.', doc:'Adaptation à la culture du liquide de ponction (germes souvent multirésistants). Sinusite fongique invasive : amphotéricine B liposomale (Mucorales) ou voriconazole/isavuconazole (Aspergillus) + débridement chirurgical.', duree:'Pas de consensus : ≈ <b>7–10 j</b> d\'antibiotiques après drainage (7 j si PAVM associée d\'évolution favorable) ; lavages par le drain jusqu\'à retour clair et apyrexie.', div:'Pas de recommandation française récente dédiée ; données issues des essais de réanimation français (Rouby 1994, Holzapfel 1999) et de revues. Terminologie : « DRP » = désobstruction rhinopharyngée (lavage de nez au sérum physiologique).', refs:['holzapfel99', 'rouby94','ssc21','sfar_pavm17', 'sinus_rev96', 'lamas00', 'sinus_braz11', 'orl_cours_sinus', 'povi_crs']},
{id:'mening', cat:'Neuro', name:'Méningite bactérienne aiguë communautaire', site:'snc',
 epi:'S. pneumoniae, N. meningitidis, Listeria (âge > 50 ans, immunodépression, alcoolisme, grossesse), H. influenzae, S. agalactiae.',
 semio:'Fièvre, raideur, troubles de conscience (triade complète < 50 %) ; purpura (méningocoque).',
 diag:'PL immédiate sauf contre-indication (signes de focalisation, crise récente, Glasgow ≤ 11, anticoagulants) → alors hémocultures + antibiothérapie + dexaméthasone avant le scanner. LCS : cellularité, glucose (rapport LCS/sang < 0,4), protéines, lactate (> 3,8 mmol/L évoque bactérien), Gram, culture, PCR (pneumocoque, méningocoque, panel multiplex).',
 proba:'<b>Dexaméthasone</b> 10 mg q6h × 4 j juste avant/avec la 1re dose d\'antibiotique (si pneumocoque/méningocoque/H. influenzae). <b>Céfotaxime 300 mg/kg/j</b> (ou ceftriaxone 100 mg/kg/j) ; <b>+ amoxicilline 200 mg/kg/j</b> si Listeria suspectée (± gentamicine). Purpura fulminans : ceftriaxone immédiate.',
 doc:'Pneumocoque : réduction de dose ou amoxicilline selon CMI ; méningocoque : C3G ou amoxicilline ; Listeria : amoxicilline ± gentamicine.',
 duree:'Méningocoque 5 j ; H. influenzae 7 j ; pneumocoque 10 j (7 j si évolution rapidement favorable) ; S. agalactiae 14–21 j ; Listeria 21 j ; entérobactéries 21 j.',
 div:'—', refs:['spilf_mening18','spilf_durees21']},
{id:'ventri', cat:'Neuro', name:'Méningite / méningo-ventriculite nosocomiale (DVE, DVP, post-craniotomie) — protocole NAR', site:'snc',
 epi:'<b>À évoquer devant tout sepsis chez un patient à risque</b> (protocole NAR) : post-opératoire de neurochirurgie ; DVE (surtout si fuite de LCS), DVP/dérivation ; traumatisé crânien avec embarrure ou brèche ostéo-méningée. Incidence ≈ 8–10 % des DVE (2–27 %). Germes : SCN, Cutibacterium acnes, S. aureus (≈ 60 % de Gram +) ; BGN (≈ 30–40 % : Enterobacter, Klebsiella, Pseudomonas, Acinetobacter) — adapter à l\'écologie du service.',
 semio:'Diagnostic difficile : clinique aspécifique chez le cérébrolésé (fièvre, altération de conscience, dysfonction de dérivation) ; sang dans le LCS (HSA, chirurgie) ; la méningite aseptique post-opératoire/hémorragique mime l\'infection.',
 diag:'<b>Prélèvement</b> : LCS <b>distal</b> si DVE (prélevé par l\'IDE, jamais dans le sac) → bactériologie avec <b>cell-index</b> + biochimie avec <b>lactates (LCS frais)</b>. Si examen direct positif : prélèvement <b>proximal</b> pour éliminer une colonisation de la burette. Culture prolongée (≥ 10 j pour Cutibacterium).<br>'+
 '<b>Lactatorachie</b> : bonne VPP et VPN, seuil 4 à 5 mmol/L selon la littérature (moins fiable si HSA récente). <b>LCR score</b> : VPN élevée. <b>Cell-index</b> = [GB LCS / GR LCS] / [GB sang / GR sang] : c\'est sa <b>cinétique</b> qui compte (augmentation en faveur de l\'infection).<br>'+
 '<table class="tbl tx"><tr><th colspan="2">LCR score (1 point par item, protocole NAR)</th></tr>'+
 '<tr><td>Leucocytes LCS</td><td>≥ 500/mm³</td></tr><tr><td>Polynucléaires neutrophiles</td><td>≥ 80 %</td></tr><tr><td>Glucose LCS / sérum</td><td>≤ 0,40</td></tr><tr><td>Lactatorachie</td><td>≥ 4 mmol/L</td></tr></table>'+
 '<b>Algorithme NAR</b><br>'+
 '1. Contexte clinique évocateur → LCS distal (cell-index, lactates).<br>'+
 '2. <b>LCR score ≤ 1 et lactatorachie &lt; 4 mmol/L et autre point d\'appel</b> → <b>pas d\'antibiothérapie spécifique</b> (traiter l\'autre foyer).<br>'+
 '3. <b>LCR score ≥ 2 et/ou lactatorachie ≥ 4 mmol/L et/ou cell-index en augmentation</b> → discussion collégiale et avis du référent → antibiothérapie probabiliste <b>ceftazidime (ou méropénème) + linézolide (ou vancomycine)</b>.<br>'+
 '4. <b>Culture du LCS négative à J3</b> → arrêt de l\'anti-BGN, poursuite de l\'anti-Gram + .<br>'+
 '5. <b>Culture négative à J5</b> → méningite aseptique : arrêt des antibiotiques ; méningite non documentée (forte suspicion clinique) : poursuite de l\'anti-Gram + .<br>'+
 '6. <b>Culture positive</b> → avis du référent, antibiothérapie ≥ 14 j adaptée à l\'antibiogramme.<br>'+
 '<b>Mesures associées</b> : TDM injectée avec temps tardif à J5 (abcès, ventriculite, empyème) ; DVE : <b>changement dans les 48 h</b> suivant le début de l\'antibiothérapie, ou ablation si possible.',
 proba:'<b>Protocole NAR</b> — association :<br>• <b>Anti-BGN anti-Pseudomonas</b> : <b>ceftazidime</b> 2 g en dose de charge puis 100 mg/kg/j IVSE (1re intention) ou <b>méropénème</b> (2e intention : colonisation BLSE, écologie).<br>• <b>Anti-Gram +</b> : <b>linézolide 600 mg × 3/j</b> IVL (1re intention) ou <b>vancomycine</b>.<br>'+
 '<table class="tbl tx"><tr><th>Molécule</th><th>Doses méningées (NAR)</th><th>C max</th></tr>'+
 '<tr><td>Ceftazidime</td><td>2 g puis 100 mg/kg/j IVSE</td><td>80 mg/mL</td></tr>'+
 '<tr><td>Méropénème</td><td>2 g puis 2 g × 3/j IVL sur 3 h</td><td>80 mg/mL</td></tr>'+
 '<tr><td>Céfépime</td><td>2 g puis 6 g/24 h IVSE ; dosage systématique à 48 h ± EEG (neurotoxicité)</td><td>100 mg/mL</td></tr>'+
 '<tr><td>Linézolide</td><td>600 mg × 3/j IVL (ou IVSE)</td><td>Déjà dilué</td></tr>'+
 '<tr><td>Vancomycine</td><td>DC 30 mg/kg IVL sur 2 h puis 60 mg/kg/j IVSE ; cible plasmatique 30–40 mg/L (néphrotoxicité : surveillance rapprochée)</td><td>80 mg/mL (VVC)</td></tr>'+
 '<tr><td>Céfotaxime</td><td>200 mg/kg/j IVSE (300 mg/kg/j si S. pneumoniae)</td><td>20 mg/mL</td></tr>'+
 '<tr><td>Ceftriaxone</td><td>2 g × 3/j IVL 10 min (100 mg/kg/j si S. pneumoniae)</td><td>20 mg/mL</td></tr>'+
 '<tr><td>Amoxicilline</td><td>2 g puis 200 mg/kg/j</td><td>20 mg/mL</td></tr>'+
 '<tr><td>Cloxacilline</td><td>2 g puis 200 mg/kg/j IVSE ou IVL en 4–6 prises</td><td>50 mg/mL</td></tr></table>',
 doc:'<b>Principes</b><br>• Adapter à l\'antibiogramme dès la documentation ; privilégier une molécule à <b>bonne diffusion méningée</b>, aux doses méningées du protocole NAR (tableau du traitement probabiliste).<br>• <b>Contrôle de la source</b> : changement de la DVE dans les 48 h suivant le début de l\'antibiothérapie, ou ablation ; retrait du matériel infecté (DVP) avec dérivation externe temporaire.<br>• <b>Staphylocoques</b> : bithérapie (+ rifampicine) si le matériel est maintenu ou si l\'évolution est mauvaise.<br><table class="tbl tx stack"><tr><th>Germe</th><th>1re intention (doses méningées)</th><th>Alternatives / remarques</th></tr><tr><td><b>Staphylocoque méti-S</b><br>(<a href="#g-saureus">S. aureus</a>, <a href="#g-scn">SCN</a>)</td><td data-label="1re intention"><b>Cloxacilline</b> 2 g puis 200 mg/kg/j IVSE ou IVL en 4–6 prises</td><td data-label="Alternatives / remarques">Céfazoline : diffusion méningée insuffisante. Allergie : linézolide ou vancomycine (doses méningées). <b>+ rifampicine</b> 600 mg × 2/j si matériel maintenu (DVE, DVP) ou mauvaise évolution (résistance à la rifampicine non rare : antibiogramme).</td></tr><tr><td><b>Staphylocoque méti-R</b><br>(SARM, SCN méti-R : la majorité des SCN)</td><td data-label="1re intention"><b>Linézolide</b> 600 mg × 3/j IVL <b>ou vancomycine</b> DC 30 mg/kg IVL 2 h puis 60 mg/kg/j IVSE, cible 30–40 mg/L (NAR)</td><td data-label="Alternatives / remarques">IDSA 2017 : daptomycine ou cotrimoxazole en alternative. <b>+ rifampicine</b> si matériel maintenu ou mauvaise évolution.</td></tr><tr><td><b><a href="#g-cuti">Cutibacterium acnes</a></b></td><td data-label="1re intention"><b>Pénicilline G</b> 4 MUI × 6/j (IDSA 2017) ou <b>amoxicilline</b> 2 g puis 200 mg/kg/j (doses méningées NAR)</td><td data-label="Alternatives / remarques">Céfotaxime ou ceftriaxone ; vancomycine ou linézolide. Métronidazole : résistance naturelle. Culture prolongée ≥ 10 j ; retrait ou changement du matériel.</td></tr><tr><td><b>Entérocoque amoxicilline-S</b><br>(<a href="#g-efaecalis">E. faecalis</a>)</td><td data-label="1re intention"><b>Amoxicilline</b> 2 g puis 200 mg/kg/j</td><td data-label="Alternatives / remarques">Amoxicilline-R (<a href="#g-efaecium">E. faecium</a>) : vancomycine (doses méningées). Vancomycine-R (ERV) : linézolide 600 mg × 3/j (IDSA 2017).</td></tr><tr><td><b>Entérobactéries groupes 0, 1, 2</b>, sans BLSE<br>(<a href="#g-ecoli">E. coli</a>, <a href="#g-kpneu">K. pneumoniae</a>, <a href="#g-pmirabilis">P. mirabilis</a>…)</td><td data-label="1re intention"><b>Céfotaxime</b> 200 mg/kg/j IVSE après dose de charge</td><td data-label="Alternatives / remarques">Ceftriaxone (doses méningées). Allergie (IDSA 2017) : aztréonam, fluoroquinolone ou cotrimoxazole selon l\'antibiogramme.</td></tr><tr><td><b>Groupe 3 faiblement mutant</b><br>(<a href="#g-morganella">Morganella, Providencia</a>, <a href="#g-serratia">Serratia</a>), souche sauvage</td><td data-label="1re intention">Foyer contrôlé : <b>céfotaxime 200 mg/kg/j IVSE</b></td><td data-label="Alternatives / remarques">Fort inoculum ou DVE laissée en place : <b>céfépime 6 g/24 h IVSE</b> (IDSA 2024). Allergie ou échec : <b>méropénème</b>. Colistine inactive (résistance naturelle), y compris en intraventriculaire.</td></tr><tr><td><b>HECK-Yes</b><br>(<a href="#g-ecloacae">Enterobacter</a>, <a href="#g-cfreundii">C. freundii</a>, <a href="#g-kaerogenes">K. aerogenes</a>, <a href="#g-hafnia">Hafnia</a>…)</td><td data-label="1re intention"><b>Céfépime</b> 2 g puis 6 g/24 h IVSE si CMI ≤ 1 mg/L et pas de BLSE ; dosage à 48 h ± EEG</td><td data-label="Alternatives / remarques">Pas de C3G (sélection de mutants déréprimés). BLSE : méropénème. Si S : fluoroquinolone ou cotrimoxazole (bonne diffusion méningée).</td></tr><tr><td><b>Entérobactérie BLSE</b></td><td data-label="1re intention"><b>Méropénème</b> 2 g puis 2 g × 3/j IVL sur 3 h</td><td data-label="Alternatives / remarques"><b>Carbapénémase (EPC)</b> : avis du référent ; choix selon l\'enzyme (IDSA 2024 : ceftazidime-avibactam pour KPC ou OXA-48 ; + aztréonam pour les métallo-β-lactamases). Données méningées limitées : discuter la voie intraventriculaire.</td></tr><tr><td><b><a href="#g-paeru">Pseudomonas aeruginosa</a></b></td><td data-label="1re intention"><b>Ceftazidime</b> 2 g puis 100 mg/kg/j IVSE (NAR) ; sinon céfépime (6 g/24 h IVSE) ou méropénème selon l\'antibiogramme</td><td data-label="Alternatives / remarques">Pip-tazo : diffusion méningée insuffisante. Souche résistante ou DTR : avis du référent, association IV + voie intraventriculaire (amikacine, colistiméthate).</td></tr><tr><td><b><a href="#g-abaum">Acinetobacter baumannii</a></b></td><td data-label="1re intention">Carbapénème-S : <b>méropénème</b> 2 g × 3/j IVL sur 3 h</td><td data-label="Alternatives / remarques">Résistant aux carbapénèmes : avis du référent ; colistine IV <b>+ colistiméthate intraventriculaire</b> (IDSA 2017).</td></tr><tr><td><b>Candida</b><br>(<a href="#g-calbicans">C. albicans</a> et autres)</td><td data-label="1re intention"><b>Amphotéricine B liposomale</b> 5 mg/kg/j ± <b>5-fluorocytosine</b> 25 mg/kg × 4/j (IDSA 2016)</td><td data-label="Alternatives / remarques">Relais par fluconazole 400–800 mg/j (6–12 mg/kg/j) si souche S et évolution favorable. <b>Échinocandines contre-indiquées</b> (diffusion méningée). <b>Retrait du matériel</b> indispensable.</td></tr><tr><td><b><a href="#g-asp">Aspergillus</a></b> et autres moisissures</td><td data-label="1re intention"><b>Voriconazole</b> (IDSA 2017)</td><td data-label="Alternatives / remarques">Dosage de la résiduelle (variabilité). Avis du référent.</td></tr></table><b>Fluoroquinolone en association (BGN)</b> : pas de recommandation ni de donnée clinique propre ; DVE changée ou retirée → pas d\'indication ; à discuter avec le référent si matériel non retirable ou cultures persistantes (<a href="#pharmaco-bio">Anti-biofilm</a>).<br><b>Cultures du LCS répétées positives</b> sous traitement adapté : poursuivre 10–14 j après la dernière culture positive (IDSA 2017).<br><b>Voie intraventriculaire</b> (IDSA 2017) : si échec clinique ou microbiologique, ou BGN multirésistant.<br>• Doses : vancomycine 5–20 mg/j (10 mg usuel) ; gentamicine 4–8 mg/j ; amikacine 5–50 mg/j (30 mg usuel) ; colistiméthate 125 000 UI/j (≈ 10 mg de colistiméthate) ; daptomycine 2–5 mg/j.<br>• Clamper la DVE 15–60 min ; fréquence selon le débit de la DVE (&lt; 50 mL/j → toutes les 72 h ; 50–100 → 48 h ; ≥ 100 → 24 h, avec majoration de dose au-delà de 150 mL/j).',
 duree:'<b>Protocole NAR</b> : arrêt précoce si LCS stérile (prélèvement réalisé hors antibiothérapie) — anti-BGN arrêté à J3, anti-Gram + à J5. Méningite documentée : <b>staphylocoque 14 j</b> et <b>BGN 21 j</b> après changement/ablation de la DVE. <b>Abcès ou empyème : 6 à 12 semaines</b>.<br><b>IDSA 2017</b> (pour comparaison) : SCN ou C. acnes avec peu de réaction du LCS (pléiocytose minime, glucose normal, peu de symptômes) 10 j ; SCN ou C. acnes avec pléiocytose, hypoglycorachie ou signes systémiques 10–14 j ; S. aureus ou BGN 10–14 j (21 j proposés par certains pour les BGN).',
 div:'Le protocole NAR (CHU de Bordeaux, 2025) diffère de l\'IDSA 2017 sur trois points : <b>linézolide en 1re intention</b> anti-Gram + (IDSA : vancomycine), <b>ceftazidime en continu</b> préférée au céfépime (neurotoxicité), et <b>cible de vancocinémie 30–40 mg/L</b> en doses méningées (au-dessus de la cible usuelle 20–25 mg/L). Il n\'existe pas de RFE SFAR/SPILF récente sur ce sujet ; l\'app retient le protocole NAR, conformément au choix de l\'équipe.',
 refs:['nar25','idsa_vent17','jni_neuro23','spilf_durees21','idsa_amr24','idsa_cand16']},
{id:'abces', cat:'Neuro', name:'Abcès cérébral et empyème — protocole NAR', site:'snc', epi:'<b>Empyème</b> : collection sous- ou extradurale ; <b>abcès</b> : collection intraparenchymateuse ; mortalité 15–20 %. Étiologies (protocole NAR) : <b>contiguïté ≈ 50 %</b> (ORL, dentaire, post-craniotomie), <b>hématogène ≈ 30 %</b> (endocardite, foyer dentaire…), inconnue ≈ 20 %. Germes : streptocoques du groupe milleri, anaérobies (contiguïté) ; S. aureus (hématogène, post-opératoire) ; BGN, Cutibacterium (post-opératoire). <b>Immunodéprimé</b> : VIH → toxoplasmose, tuberculose, cryptococcose ; transplanté → Aspergillus (&lt; 1 an), <b>Nocardia</b> (&gt; 1 an) ; Listeria.', semio:'Céphalées, déficit focal, crises, HTIC ; fièvre inconstante.', diag:'IRM (diffusion), <b>ponction-biopsie chirurgicale</b> (sauf VIH) : cultures aéro/anaérobies, cultures spécifiques si immunodéprimé (Nocardia…), <b>ARN 16S</b> si cultures négatives ; hémocultures, PL hors contre-indication. Recherche de porte d\'entrée (ORL, cutanée, digestive, pulmonaire) et de localisation secondaire (spondylodiscite, endocardite) : <b>dento-TDM</b> si intubé (cone beam sinon), TDM TAP, ETT ± ETO. Recherche d\'immunodépression : <b>sérologie VIH systématique</b> (avant une éventuelle biopsie), NFS, électrophorèse des protéines, complément (CH50, C3, C4). Filière d\'éradication du foyer dentaire (CHU de Bordeaux, avec le référent infectieux).', proba:'<b>Protocole NAR</b> :<br>• Immunocompétent, <b>communautaire</b> : <b>céfotaxime 200 mg/kg/j</b> (max 12 g/j) IVSE + <b>métronidazole 500 mg × 3/j</b> IVL 1 h (= ESCMID 2024).<br>• Immunocompétent, <b>post-opératoire</b> : <b>céfépime 2 g × 3/j</b> IVL + <b>linézolide 600 mg × 2 à 3/j</b> IVL (sauf exposition au linézolide dans les 6 derniers mois).<br>• <b>Transplanté d\'organe / hématologie</b> : ajouter <b>cotrimoxazole + voriconazole</b>.<br>• <b>VIH</b> : ajouter <b>pyriméthamine-sulfadiazine</b> (+ acide folinique) ; la biopsie n\'est pas systématique, une bonne réponse au traitement d\'épreuve peut confirmer une toxoplasmose.', doc:'Adaptation à la documentation ; relais oral possible après 2 sem IV si évolution favorable (ESCMID 2024). Drainage/exérèse chirurgicale selon taille, localisation et effet de masse ; empyème : évacuation chirurgicale en règle.', duree:'<b>6 à 8 semaines</b> (protocole NAR) ; ESCMID 2024 : 6 sem (4 sem si exérèse chirurgicale complète).', div:'Le protocole NAR (6–8 sem, céfépime + linézolide en post-opératoire) est cohérent avec ESCMID 2024 (6 sem, vancomycine + méropénème ou céphalosporine anti-Pseudomonas + métronidazole en post-opératoire).', refs:['nar25', 'escmid_abces24', 'spilf_durees21']},
{id:'enceph', cat:'Neuro', name:'Méningo-encéphalite infectieuse (HSV, VZV, Listeria, tuberculose, arbovirus) et diagnostics différentiels', site:'snc', epi:'<b>HSV-1</b> (1re cause d\'encéphalite sporadique grave), <b>VZV</b> (sujet âgé, immunodéprimé, vascularite), <b>Listeria</b> (rhombencéphalite ; âge, grossesse, immunodépression, cirrhose), <b>tuberculose</b>, entérovirus, arboviroses (encéphalite à tiques en Alsace/Rhône-Alpes, West Nile dans le Sud), VIH. Diagnostics différentiels : <b>encéphalite auto-immune</b> (anti-NMDAR, anti-LGI1…, y compris après une encéphalite herpétique), états de mal non convulsifs, causes métaboliques/toxiques.', semio:'Fièvre + troubles de conscience ou du comportement, crises, déficits focaux, troubles du langage ; atteinte des nerfs crâniens et syndrome cérébelleux (Listeria).', diag:'<b>PL</b> (cytologie lymphocytaire, protéines, glucose, lactates ; PCR HSV-1/2, VZV, entérovirus ; culture/PCR Listeria ; recherche de BK ; conserver un tube) ; <b>IRM</b> (lésions temporales internes : HSV) ; <b>EEG</b> (activité périodique, état de mal infraclinique) ; sérologie VIH ; anticorps neuronaux sang/LCS si bilan infectieux négatif. <b>Refaire la PCR HSV à J3–J7</b> si négative précoce et forte suspicion.', proba:'<b>Aciclovir 10 mg/kg q8h IV</b> dès la suspicion, sans attendre la PCR (poids idéal ou ajusté chez l\'obèse ; hydratation, risque de néphropathie cristalline ; adaptation à la fonction rénale) <b>+ amoxicilline 200 mg/kg/j</b> si Listeria possible (SPILF 2017) ; ± traitement antituberculeux si orientation (rhombencéphalite, hyponatrémie, glycorachie basse).', doc:'<b>HSV</b> : aciclovir 14–21 j (21 j si immunodéprimé ; prolonger si PCR encore positive en fin de traitement). <b>VZV</b> : aciclovir 10–15 mg/kg q8h 10–14 j (± corticoïdes si vascularite). <b>Listeria</b> : amoxicilline 21 j (+ gentamicine les premiers jours ; cotrimoxazole si allergie). <b>Tuberculose</b> : quadrithérapie + dexaméthasone. <b>Auto-immune</b> : immunothérapie (corticoïdes, IgIV/échanges plasmatiques) ; rechercher un tératome ovarien (anti-NMDAR).', duree:'HSV 14–21 j ; VZV 10–14 j ; Listeria 21 j.', div:'—', refs:['spilf_enceph17', 'epopi']},
{id:'iia', cat:'Abdominal', name:'Infection intra-abdominale (péritonite communautaire / associée aux soins / post-opératoire) — RFE SFAR 2026', site:'abdo',
 epi:'<b>Communautaire</b> : entérobactéries (E. coli), streptocoques, anaérobies (B. fragilis). <b>Associée aux soins / post-opératoire</b> : entérobactéries BLSE/AmpC, P. aeruginosa, entérocoques (dont E. faecium, ampicilline-R), Candida.<br>'+
 '<b>Facteurs de risque de bactéries résistantes (RFE 2026, Tableau 1)</b><br>'+
 '• <b>BLSE</b> (IIA communautaire) : infection/colonisation à BLSE &lt; 6 mois ; amox-clav, C2G/C3G ou FQ dans les 6 mois ; voyage en zone d\'endémie &lt; 3 mois ; EHPAD/SLD avec dispositif invasif permanent (sonde urinaire, gastrostomie) ; prévalence locale élevée.<br>'+
 '• <b>BMR</b> (IIA associée aux soins) : C3G ou FQ dans les 3 mois ; portage &lt; 3 mois d\'une BLSE ou d\'un P. aeruginosa ceftazidime-R (tout site) ; hospitalisation à l\'étranger dans les 12 mois ; EHPAD/SLD avec dispositif invasif permanent ; échec d\'un traitement par C3G, FQ ou pip-tazo ; récidive &lt; 15 j d\'une infection traitée ≥ 3 j par pip-tazo.<br>'+
 '• <b>Entérocoque ampicilline-R</b> : origine hépatobiliaire suspectée ; transplantation hépatique, immunodépression ; patient déjà sous antibiotiques ou C3G préalable.<br>'+
 '<b>Facteurs de risque de Candida fluconazole-R (Tableau 4)</b> : exposition récente aux azolés, écologie hospitalière, IRC, neutropénie, tumeur solide ; espèces naturellement R ou de sensibilité diminuée : N. glabratus (C. glabrata), P. kudriavzevii (C. krusei), C. auris…',
 semio:'<b>Contrôle de la source</b> : en urgence et par chirurgie avec lavage de toute la cavité si instabilité hémodynamique (R1.1.1, grade 1) ; « damage control » (laparotomie écourtée) si instabilité non contrôlée en peropératoire, reprise à 24–48 h (R1.1.2) ; cœlioscopie possible si hémodynamique stable et lésion accessible (R1.1.3) ; IIA post-opératoire avec collection accessible chez un patient stable : endoscopie interventionnelle ou drainage percutané en 1re intention (R1.1.4). Diverticulite Hinchey III sans sepsis : pas de lavage seul, résection sigmoïdienne avec anastomose ± iléostomie (R1.1.5).<br>'+
 '<b>Orientation</b> : soins critiques systématiques si sepsis ou choc septique (R1.3.1, grade 1) ; sinon décision selon âge &gt; 60 ans, comorbidités, péritonite généralisée (R1.3.2) ; scores CPIRO, WSES SSS ou PIPAS utilisables (R1.3.3).',
 diag:'Prélèvements per-opératoires (liquide péritonéal, pas d\'écouvillon) avec examen direct (levures !) ; hémocultures.<br><b>Surveillance (R2.1.1–2.1.2)</b> : pendant les 5 premiers jours post-opératoires, pas de PCT/CRP systématiques, pas de reprise systématique (hors damage control ou doute sur la vitalité digestive), pas de culture des liquides de drainage, pas de TDM systématique si évolution favorable.<br><b>Évolution défavorable</b> : phase précoce (≤ 72 h) — fièvre, iléus ou défaillance persistante → suspecter une complication ou un contrôle imparfait de la source, reprise en urgence (R3.2.1) ; TDM sur discussion multidisciplinaire, pas de CRP/PCT, pas de culture du drain (R3.2.2). Phase tardive (&gt; 72 h) : TDM TAP injecté (± opacification si chirurgie gastrique/colique) (R3.2.3). Approche mini-invasive si patient stable (R3.1.2).',
 proba:'<b>IIA communautaire (Figure 1)</b><br>'+
 '• Sans sepsis ni choc : <b>céfotaxime ou ceftriaxone + métronidazole</b> (R1.2.1) ; pas de prise en compte des BLSE (R1.2.2).<br>'+
 '• Sepsis : idem ; carbapénème seulement si antécédent documenté de colonisation/infection à BLSE dans les 6 mois (R1.2.3).<br>'+
 '• Choc septique sans FdR de BLSE : <b>pipéracilline-tazobactam</b> (R1.2.4) ; avec ≥ 1 FdR de BLSE : <b>carbapénème</b> selon la prévalence locale (R1.2.5).<br>'+
 '• Allergie avérée (céphalosporines et carbapénèmes impossibles) : lévofloxacine + métronidazole ou moxifloxacine seule (contrôle du QTc) ; si FQ contre-indiquées : tigécycline (préférée en communautaire) ou éravacycline, réévaluation à 48 h (R1.2.11).<br>'+
 '<b>IIA associée aux soins, 1er épisode (Figure 2)</b><br>'+
 '• Sans FdR de BMR, y compris sepsis/choc : <b>céfépime + métronidazole</b> (R1.2.6, grade 1) — STP du céfépime (neurotoxicité) ; si STP impossible et selon l\'écologie : <b>pipéracilline-tazobactam</b> (R1.2.7).<br>'+
 '• <b>≥ 2 FdR de BMR</b>, ou <b>≥ 1 FdR en cas de sepsis/choc</b> : <b>imipénème ou méropénème</b> (R1.2.10, grade 1).<br>'+
 '• Entérocoques : choc septique sous céfépime-métronidazole → ajouter <b>linézolide, vancomycine ou teicoplanine</b> (R1.2.8) ; sous pip-tazo et FdR d\'entérocoque ampicilline-R → ajouter linézolide, vancomycine ou teicoplanine (R1.2.9).<br>'+
 '• Allergie avérée : (1) ciprofloxacine + métronidazole ± linézolide/vancomycine/teicoplanine ; (2) aztréonam + métronidazole ± linézolide/vancomycine/teicoplanine ; (3) tigécycline + ciprofloxacine ou éravacycline + ciprofloxacine (R1.2.12).<br>'+
 '• <b>Plus d\'aminoside systématique</b> en probabiliste (pas de bénéfice démontré).<br>'+
 '<b>Antifongique (Figure 3, R1.2.13)</b> — IIA communautaire avec sepsis/choc ou associée aux soins : traiter si <b>levures à l\'examen direct</b> du liquide péritonéal ou si <b>≥ 3 critères</b> parmi : défaillance hémodynamique, sexe féminin, chirurgie sus-mésocolique, antibiothérapie &gt; 48 h (Peritonitis score). Puis si défaillance hémodynamique ou IIA associée aux soins : <b>échinocandine</b> si FdR de souche fluconazole-R ou complication post-opératoire, sinon <b>fluconazole</b>. Pas d\'antifongique en IIA communautaire sans gravité, même si levures à l\'examen direct.<br>'+
 '<b>Complication post-opératoire (R3.3.x)</b> : probabiliste couvrant entérobactéries multirésistantes (dont BLSE), P. aeruginosa et E. faecium, selon l\'écologie locale et du patient (R3.3.1) ; antifongique probabiliste systématique (échinocandine) si mauvaise évolution avec gravité hémodynamique ou levures à l\'examen direct (R3.3.5) ; STP (R3.3.3).',
 doc:'<b>Désescalade</b> après résultats bactériologiques si évolution favorable après contrôle de la source (R2.4.1) ; désescalade antifongique possible si non neutropénique, source contrôlée, prélèvements interprétables, amélioration à 48–72 h, traitement initial optimisé et &gt; 24 h restant (R2.4.2). Adaptation aux prélèvements de reprise ou aux hémocultures seules si prélèvements non contributifs (R3.3.2). Antifongique probabiliste avec culture négative ou indisponible : BDG à J0 et J3, arrêt précoce si les deux sont négatifs (R2.3.2).<br><br>'+
 '<b>Posologies proposées en réanimation (Annexe 1)</b> — fonction rénale normale / hyperclairance (ClCr mesurée &gt; 130 mL/min) :'+
 '<table class="tbl tx"><tr><th>Molécule</th><th>Réanimation</th><th>Hyperclairance</th></tr>'+
 '<tr><td>Céfépime</td><td>DC 2 g (30 min) puis 3–4 g/j en continu ; STP entre H24 et H36</td><td>DC 2 g puis 6 g/j en continu ; STP</td></tr>'+
 '<tr><td>Pip-tazo</td><td>DC 4 g (30 min) puis 16 g/j en continu</td><td>DC 4 g puis 20 g/j en continu</td></tr>'+
 '<tr><td>Méropénème</td><td>3 g/j en continu</td><td>6 g/j en continu</td></tr>'+
 '<tr><td>Imipénème</td><td>1 g q8h (30 min)</td><td>—</td></tr>'+
 '<tr><td>Céfotaxime</td><td>2 g q8h (30 min) ou continu</td><td>NA*</td></tr>'+
 '<tr><td>Ceftriaxone</td><td>2 g q12h (30 min)</td><td>NA*</td></tr>'+
 '<tr><td>Ertapénem</td><td>1 g q12h</td><td>—</td></tr>'+
 '<tr><td>Métronidazole</td><td>500 mg q8h</td><td>—</td></tr>'+
 '<tr><td>Amikacine</td><td>25–30 mg/kg de poids ajusté, 1 fois/j</td><td>—</td></tr>'+
 '<tr><td>Ciprofloxacine</td><td>400 mg q8h</td><td>NA*</td></tr>'+
 '<tr><td>Lévofloxacine</td><td>500 mg q12h</td><td>NA*</td></tr>'+
 '<tr><td>Moxifloxacine</td><td>400 mg/j</td><td>—</td></tr>'+
 '<tr><td>Tigécycline</td><td>DC 100 mg puis 100 mg q12h</td><td>—</td></tr>'+
 '<tr><td>Éravacycline</td><td>1 mg/kg q12h</td><td>—</td></tr>'+
 '<tr><td>Vancomycine</td><td>DC 30 mg/kg (1 h) puis 10–30 mg/kg/j en continu selon la fonction rénale</td><td>DC 30 mg/kg puis 40 mg/kg/j en continu</td></tr>'+
 '<tr><td>Teicoplanine</td><td>12 mg/kg q12h pendant 3–5 j puis 12 mg/kg/j</td><td>NA*</td></tr>'+
 '<tr><td>Linézolide</td><td>600 mg q8–12h ; continu chez l\'obèse</td><td>1800 mg/j en continu (STP)</td></tr>'+
 '<tr><td>Caspofungine</td><td>DC 140 mg puis 1 mg/kg/j</td><td>—</td></tr>'+
 '<tr><td>Micafungine</td><td>DC 150 mg puis 100 mg/j (150 mg si obèse ; 200 mg/j possible : sous-exposition fréquente)</td><td>—</td></tr>'+
 '<tr><td>Fluconazole</td><td>DC 12 mg/kg puis 6 mg/kg/j</td><td>NA*</td></tr></table>'+
 '<span class="muted small">* NA : pas de données ; débuter comme chez le normoclairant puis adapter selon les dosages. Obèse : abxbmi ; insuffisance rénale : GPR. Dilutions et perfusions prolongées/continues : recommandations SPILF/SFPC 2025 (Ourghanlian).</span>',
 duree:'<b>Appendicite non compliquée</b>, source contrôlée : antibioprophylaxie seule (R2.2.1). <b>Appendicite compliquée</b> : <b>2 j</b> (R2.2.2). <b>IIA communautaire compliquée</b> (hors appendicite), source contrôlée : <b>4 j</b>, y compris sepsis initial ou drainage percutané/endoscopique (R2.2.3, grade 1). <b>IIA associée aux soins</b> (hors post-opératoire) sans sepsis : <b>4 j</b> (R2.2.4) ; avec sepsis/choc : <b>8 j</b> (R2.2.5). <b>Complication post-opératoire</b> : <b>8 j</b> après contrôle de la source et amélioration ; au-delà, discussion multidisciplinaire (R3.3.4). <b>Antifongique</b> débuté d\'emblée, culture positive à Candida : <b>8 j</b> si source contrôlée rapidement, évolution favorable et pas de candidémie (R2.3.1) ; sinon pas de recommandation.',
 div:'<b>Champ de la RFE</b> : IIA nécessitant une intervention (chirurgie, endoscopie ou radiologie). <b>Exclues</b> : infections primaires associées à la cirrhose, infections biliaires et abcès hépatiques isolés, enfants, infections sans prise en charge interventionnelle (dont appendicites non opérées), patients en aplasie ou greffés d\'organe solide. Une infection après une <b>chirurgie abdominale programmée</b> relève du champ 1 (IIA associée aux soins, 1er épisode) ; le <b>champ 3</b> (R3.x) concerne les complications survenant après une première intervention pour une IIA.<br>RFE SFAR 2026 élaborée <b>avec la SPILF et la SFPT</b> (et SFM, SFR, chirurgiens, endoscopistes) : <b>pas de divergence SFAR/SPILF</b> ; elle <b>remplace la RFE SFAR 2015</b>. Changements par rapport à 2015 : céfépime + métronidazole en 1re intention dans l\'IIA associée aux soins (pip-tazo en alternative), abandon de l\'aminoside systématique, carbapénème selon le nombre de FdR de BMR et la gravité, durées raccourcies (4 j en communautaire, alignées sur la SPILF 2021 — l\'ancienne divergence 5 j/4 j disparaît), BDG J0/J3 pour arrêter l\'antifongique. La témocilline n\'est pas abordée par la RFE.',
 refs:['sfar_iia26','ourghanlian25','merino18','has_carba19','spilf_durees21','ecmm_cand25','fundicu24','sfar_bl2019','sfar_iia15']},
{id:'cdi', cat:'Abdominal', name:'Infection à Clostridioides difficile (ICD) — y compris forme fulminante', site:'abdo', epi:'Première cause de diarrhée nosocomiale. FdR : antibiotiques (clindamycine, FQ, C3G, pénicillines + inhibiteur), âge, hospitalisation, IPP, immunodépression, MICI. Souche hypervirulente 027.', semio:'Diarrhée ≥ 3 selles non moulées/24 h. <b>Gravité (ESCMID 2021)</b> : fièvre &gt; 38,5 °C, leucocytes &gt; 15 G/L, créatinine augmentée de &gt; 50 %. <b>Forme fulminante/compliquée</b> : hypotension, choc, lactates élevés, <b>iléus</b> (diarrhée parfois absente !), <b>mégacôlon toxique</b>, perforation.', diag:'Algorithme en 2 temps : GDH ou PCR toxine B (sensibles) puis toxines libres A/B (spécifiques de la maladie). Ne pas tester les selles moulées, pas de test de guérison. TDM abdominale si forme grave (colite, mégacôlon, perforation).', proba:'<b>Arrêter les antibiotiques non indispensables</b> et les IPP.<br>• Formes non sévères et sévères : <b>fidaxomicine 200 mg × 2/j 10 j</b> (préférée : moins de récidives) ; alternative : <b>vancomycine PO 125 mg × 4/j 10 j</b> ; métronidazole seulement si aucune des deux n\'est disponible (forme non sévère).<br>• <b>Fulminante</b> : <b>vancomycine 500 mg × 4/j</b> par sonde gastrique + <b>métronidazole IV 500 mg × 3/j</b> ; si iléus : <b>lavements de vancomycine</b> 500 mg dans 100 mL q6h ; avis chirurgical précoce.<br>• <b>Chirurgie</b> : perforation, mégacôlon, choc réfractaire, péritonite → colectomie subtotale ou iléostomie de dérivation avec lavage colique.', doc:'Première récidive : fidaxomicine (ou vancomycine si fidaxomicine utilisée initialement) ; récidives multiples : <b>transplantation de microbiote fécal</b> ; bezlotoxumab n\'est plus commercialisé. <b>Hygiène</b> : précautions contact, lavage des mains à l\'<b>eau et au savon</b> (les SHA sont inactives sur les spores), bionettoyage sporicide.', duree:'10 j.', div:'—', refs:['escmid_cdi21']},
{id:'endoc', cat:'Cardiovasculaire', name:'Endocardite infectieuse (valve native, prothèse, matériel intracardiaque) — ESC 2023', site:'endo', epi:'Germes : <b>S. aureus</b> (1re cause, ≈ 30 %), streptocoques oraux, <b>S. gallolyticus</b> (lésion colique → coloscopie), <b>E. faecalis</b> (sujet âgé, porte d\'entrée urinaire/digestive), SCN (prothèse précoce, matériel), HACEK, <b>Candida</b> (prothèse, toxicomanie IV, CVC, nutrition parentérale), hémocultures négatives (≈ 10–20 % : antibiothérapie préalable, Coxiella burnetii, Bartonella, Tropheryma whipplei, Brucella).<br>FdR : prothèse valvulaire/TAVI, antécédent d\'EI, cardiopathie congénitale, toxicomanie IV, stimulateur/DAI, hémodialyse, cathéters.<br><b>Motifs de réanimation</b> : insuffisance cardiaque/choc cardiogénique (régurgitation aiguë), choc septique, <b>complications neurologiques (20–40 %)</b> : AVC ischémique embolique, hémorragie intracrânienne, anévrisme mycotique, abcès, méningite ; insuffisance rénale.', semio:'<b>Critères de Duke modifiés ESC 2023 / Duke-ISCVID 2023</b><br>• <b>Majeurs</b> : (1) microbiologique — germe typique sur ≥ 2 hémocultures séparées (S. aureus, E. faecalis, streptocoques oraux, S. gallolyticus, HACEK…), bactériémie persistante, ou Coxiella (1 hémoculture ou IgG phase I &gt; 1:800), PCR/séquençage valvulaire ; (2) imagerie — végétation, abcès, pseudo-anévrisme, fistule, perforation, désinsertion prothétique récente (échographie ou TDM cardiaque), hyperfixation péri-prothétique en TEP-TDM au FDG (&gt; 3 mois après la chirurgie).<br>• <b>Mineurs</b> : prédisposition, fièvre &gt; 38 °C, phénomènes vasculaires <b>y compris détectés uniquement en imagerie</b> (emboles, infarctus/abcès spléniques ou rénaux, hémorragie cérébrale, anévrisme mycotique, Janeway), phénomènes immunologiques (glomérulonéphrite, Osler, Roth, facteur rhumatoïde), preuve microbiologique ne remplissant pas le critère majeur.<br>• <b>Certaine</b> : 2 majeurs, ou 1 majeur + 3 mineurs, ou 5 mineurs ; <b>possible</b> : 1 majeur + 1 mineur, ou 3 mineurs.', diag:'• <b>≥ 3 paires d\'hémocultures</b> (aéro + anaérobie) avant antibiotiques ; en sepsis, ne pas retarder le traitement au-delà de la 1re heure.<br>• <b>ETT puis ETO</b> (ETO recommandée (ESC 2023) dans toute suspicion, même ETT positive, pour les complications et les prothèses) ; <b>répéter l\'ETO à 5–7 j</b> si négative avec forte suspicion, et en cas de nouvelle complication.<br>• <b>TDM cardiaque</b> (abcès, pseudo-anévrisme), <b>TEP-TDM au FDG</b> (prothèse, matériel de stimulation, foyers emboliques).<br>• <b>Imagerie cérébrale</b> (IRM ± angio-IRM/angio-TDM) et corps entier (TDM TAP) : recommandées (ESC 2023) si symptômes, à envisager systématiquement dans l\'EI gauche (modifie l\'indication et le délai opératoires) ; recherche d\'anévrisme mycotique si céphalées, hémorragie ou déficit.<br>• Hémocultures négatives : sérologies Coxiella, Bartonella, Brucella, Legionella, Mycoplasma ; PCR 16S/18S et histologie sur valve ; anticorps antinucléaires/antiphospholipides (endocardite non infectieuse).<br>• Porte d\'entrée : panoramique/TDM dentaire, coloscopie (S. gallolyticus, E. faecalis), ECBU, examen cutané.<br>• <b>Endocarditis team</b> (cardiologue, chirurgien cardiaque, infectiologue, microbiologiste, imageur, ± neurologue/neuroradiologue) : obligatoire pour les formes compliquées.', proba:'<b>Probabiliste (ESC 2023)</b><br>• <b>Valve native communautaire ou prothèse tardive (&gt; 12 mois)</b> : <b>ampicilline/amoxicilline 12 g/j</b> (4–6 prises) <b>+ cloxacilline 12 g/j</b> (4–6 prises) <b>+ gentamicine 3 mg/kg/j</b> (1 injection) ; allergie : vancomycine + gentamicine.<br>• <b>Prothèse précoce (&lt; 12 mois) ou EI associée aux soins</b> : <b>vancomycine</b> (DC 25–30 mg/kg puis continu, cible 20–25 mg/L) <b>+ gentamicine 3 mg/kg/j + rifampicine 900–1200 mg/j</b> (prothèse uniquement ; débutée après 3–5 j, une fois la bactériémie contrôlée).<br>• Gentamicine : plus recommandée (ESC 2023) dans l\'EI à S. aureus sur valve native (néphrotoxicité sans bénéfice).', doc:'<table class="tbl tx"><tr><th>Germe</th><th>Valve native</th><th>Prothèse</th></tr><tr><td>Streptocoques oraux / S. gallolyticus, péni-S (CMI ≤ 0,125)</td><td>Péni G 12–18 MUI/j ou amoxicilline 100–200 mg/kg/j ou ceftriaxone 2 g/j — <b>4 sem</b> ; <b>2 sem</b> + gentamicine 3 mg/kg/j si non compliquée et fonction rénale normale</td><td>Même schéma <b>6 sem</b> (pas de schéma court)</td></tr><tr><td>Streptocoques péni-R (CMI 0,25–2)</td><td>Péni G 24 MUI/j ou amoxicilline 200 mg/kg/j ou ceftriaxone 2 g/j <b>4 sem</b> + gentamicine les 2 premières sem</td><td><b>6 sem</b> + gentamicine 2 sem</td></tr><tr><td>E. faecalis</td><td><b>Amoxicilline 200 mg/kg/j + ceftriaxone 2 g × 2/j</b> 6 sem (pas de néphrotoxicité) ; ou amoxicilline + gentamicine 2 sem (si pas de haut niveau aux aminosides) 4–6 sem</td><td>6 sem</td></tr><tr><td>S. aureus méti-S</td><td><b>Cloxacilline 12 g/j</b> (4–6 prises) ou <b>céfazoline 6 g/j</b> (3 prises ou continu) — <b>4–6 sem</b></td><td>Cloxacilline/céfazoline <b>+ rifampicine 900 mg/j</b> (3 prises) ≥ 6 sem + gentamicine 2 sem</td></tr><tr><td>S. aureus méti-R</td><td>Vancomycine (AUC 400–600 ou Css 20–25 mg/L) ou <b>daptomycine 10 mg/kg/j</b> (± fosfomycine ou cloxacilline) — 4–6 sem</td><td>+ rifampicine ≥ 6 sem + gentamicine 2 sem</td></tr><tr><td>HACEK</td><td>Ceftriaxone 2 g/j 4 sem</td><td>6 sem</td></tr><tr><td>Candida</td><td>Amphotéricine B liposomale 3–5 mg/kg/j ± flucytosine, ou échinocandine forte dose ; <b>chirurgie</b> ; puis fluconazole prolongé (suppressif si non opéré). <b>Fond d\'œil dilaté systématique</b> : si choriorétinite/endophtalmie sous échinocandine (caspofungine : faible diffusion oculaire) → <b>changer d\'antifongique</b> (AmB liposomale ± flucytosine, ou fluconazole/voriconazole si S) ± traitement intravitréen. EER continue sous caspofungine : membrane HF1400 (PAES), pas de PAN.</td><td>Idem</td></tr><tr><td>Coxiella / Bartonella</td><td>Doxycycline + hydroxychloroquine ≥ 18 mois / doxycycline + gentamicine 2 sem</td><td>Idem (Coxiella ≥ 24 mois)</td></tr></table><br><b>Relais oral (ESC 2023, d\'après POET)</b> : EI gauche à streptocoque, E. faecalis, S. aureus méti-S ou SCN, patient stable, après ≥ 10 j IV (≥ 7 j après chirurgie), sans abcès nécessitant une chirurgie, ETO contrôlée → bithérapie orale (ex. amoxicilline + moxifloxacine/linézolide/rifampicine selon germe).<br><b>Indications chirurgicales (ESC 2023)</b><br>• <b>Urgence (&lt; 24 h)</b> : insuffisance cardiaque avec choc cardiogénique ou œdème pulmonaire réfractaire (régurgitation/obstruction sévère, fistule).<br>• <b>Urgente (3–5 j)</b> : insuffisance cardiaque sans choc ; <b>infection non contrôlée</b> (abcès, pseudo-anévrisme, fistule, végétation qui augmente, désinsertion prothétique, BAV de novo) ; hémocultures positives &gt; 1 sem malgré un traitement adapté ; champignon ou germe multirésistant ; EI sur prothèse à S. aureus ou BGN non-HACEK (à discuter) ; <b>prévention embolique</b> : végétation ≥ 10 mm avec ≥ 1 embolie sous traitement adapté, ou végétation ≥ 10 mm avec dysfonction valvulaire sévère et faible risque opératoire (à discuter si ≥ 10 mm isolée).<br>• <b>Matériel de stimulation/DAI</b> : <b>extraction complète</b> du boîtier et des sondes ; réimplantation (controlatérale) après hémocultures négatives ≥ 72 h.<br><b>Complications neurologiques (neuroréanimation)</b><br>• AVC ischémique (hors coma, hors infarctus étendu) : <b>ne retarde pas</b> une chirurgie indiquée ; AIT/emboles silencieux : pas de report.<br>• <b>Hémorragie intracrânienne</b> : report de la chirurgie (en général ≥ 4 sem) sauf urgence vitale, discussion collégiale.<br>• Thrombolyse <b>contre-indiquée</b> ; thrombectomie mécanique envisageable.<br>• Anticoagulation : arrêt de tout anticoagulant en cas d\'hémorragie ; AVC ischémique sous AVK pour valve mécanique : relais par HNF (≈ 2 sem) sous surveillance ; pas d\'antiagrégant introduit pour l\'EI.<br>• Anévrisme mycotique : angio-TDM/angiographie ; traitement endovasculaire ou chirurgical si volumineux, rompu ou croissant.', duree:'Compter à partir du 1er jour d\'antibiothérapie efficace (ou de la 1re hémoculture négative) : <b>valve native 4–6 sem</b> (2 sem pour certaines EI à streptocoque péni-S non compliquées), <b>prothèse ≥ 6 sem</b>. Si culture valvulaire positive au moment de la chirurgie : reprendre une durée complète à partir de l\'intervention. Matériel de stimulation sans atteinte valvulaire : 2 sem après extraction (4–6 sem si atteinte valvulaire/sonde).', div:'Pas de recommandation française distincte : la SPILF et la Société française de cardiologie se réfèrent à l\'ESC 2023. Antibioprophylaxie des procédures (TAVI, dentaires) : recommandations françaises SFAR/SPILF.', refs:['esc_ei23', 'duke23', 'poet19', 'spilf_recos', 'doses25', 'idsa_cand16', 'ecmm_cand25', 'ema_caspo25']},
{id:'dhbn', cat:'Peau / tissus mous', name:'Infections nécrosantes des tissus mous : dermohypodermite bactérienne nécrosante (DHBN) / fasciite nécrosante (FN) / myonécrose', site:'peau', epi:'<b>Types microbiologiques</b> : <b>type I polymicrobien</b> (≈ 50–70 % : entérobactéries, anaérobies, streptocoques, entérocoques ; périnée — cf. Fournier —, paroi abdominale, post-opératoire, diabétique) ; <b>type II monomicrobien</b> : <b>streptocoque du groupe A</b> (± S. aureus, dont PVL+), membres, sujet jeune, choc toxique fréquent ; <b>type III</b> : Vibrio vulnificus (eau de mer, cirrhose), Aeromonas (eau douce) ; <b>clostridiale</b> (C. perfringens post-traumatique, C. septicum spontané → cancer colique/neutropénie) ; fongique (Mucorales : traumatisme souillé, brûlure). FdR : diabète, obésité, immunodépression, AINS (masquent l\'évolution), artériopathie, toxicomanie IV, chirurgie récente, varicelle.', semio:'Douleur <b>disproportionnée</b> par rapport aux signes locaux (souvent premier signe), œdème dépassant l\'érythème, <b>hypoesthésie</b>, bulles hémorragiques, nécrose cutanée, livedo, <b>crépitation</b>, extension rapide malgré les antibiotiques, sepsis/choc. <b>Score LRINEC</b> (CRP, leucocytes, Hb, Na, créatinine, glycémie ; ≥ 6 évocateur) : sensibilité insuffisante — un score bas n\'exclut pas le diagnostic.', diag:'<b>Diagnostic clinique et chirurgical</b> : l\'exploration chirurgicale (aspect grisâtre du fascia, absence de saignement, liquide « eau de vaisselle », perte de résistance au doigt) est diagnostique et thérapeutique. <b>TDM injectée</b> (gaz, épaississement/collection le long des fascias) seulement si elle ne retarde pas le bloc (HAS/SPILF/SFD 2019 : pas d\'examen qui retarde la prise en charge). Hémocultures, <b>prélèvements per-opératoires profonds</b> (pas d\'écouvillon superficiel), PCR SGA possibles, ± biopsie (histologie, champignons).', proba:'<b>Chirurgie en urgence</b> (débridement large de tous les tissus nécrosés), <b>réintervention systématique à 24–48 h</b> (« second look ») puis itérative jusqu\'à arrêt de la progression. Réanimation du choc.<br><b>Antibiothérapie probabiliste</b> (à forte dose, toujours associée à un <b>antitoxinique</b>) :<br>• <b>Membres / cervico-facial communautaire</b> : amoxicilline-acide clavulanique (ou C3G) <b>+ clindamycine</b> 600–900 mg q8h (ou <b>linézolide</b> 600 mg q12h si FdR de SARM ou clindamycine R).<br>• <b>Périnée / abdomen / post-opératoire / diabétique</b> : <b>pipéracilline-tazobactam</b> (DC 4 g puis 16 g/j) <b>+ clindamycine</b> (ou linézolide) ± <b>amikacine</b> 25–30 mg/kg en dose unique si choc.<br>• <b>FdR de BMR / colonisation BLSE / choc associé aux soins</b> : <b>méropénème + linézolide</b> (couvre SARM + effet antitoxinique) ± amikacine.<br>• Eau de mer (Vibrio) : C3G + doxycycline ; eau douce (Aeromonas) : C3G ou FQ (+ doxycycline).<br>• Levures/filaments à l\'examen direct ou terrain : antifongique (échinocandine ; amphotéricine B liposomale si Mucorales).', doc:'SGA : amoxicilline (ou péni G) forte dose + clindamycine (puissance antitoxinique +++, cf. fiche « Antibiothérapie antitoxinique ») ; S. aureus : cloxacilline/céfazoline (SAMS) ou vancomycine/linézolide (SARM) ; clostridies : péni G + clindamycine ; polymicrobien : désescalade selon cultures en gardant la couverture anaérobie. <b>IgIV</b> : à discuter dans le choc toxique streptococcique (avis d\'expert ; l\'essai INSTINCT n\'a pas montré de bénéfice fonctionnel dans les infections nécrosantes toutes causes). <b>Oxygénothérapie hyperbare</b> : adjuvant non validé, ne doit jamais retarder la chirurgie. Contrôle glycémique, nutrition hyperprotidique, pansements (TPN) puis reconstruction.', duree:'Pas de durée validée : poursuivre jusqu\'à l\'arrêt des débridements, stabilisation hémodynamique et amélioration clinique, puis en général <b>5–7 j</b> supplémentaires (≈ 10–15 j au total) ; antitoxinique arrêté après stabilisation (≈ 3–7 j).', div:'Recommandations françaises HAS/SPILF/SFD 2019 (prise en charge ambulatoire, urgence médico-chirurgicale sans proposition d\'antibiothérapie hospitalière) → schémas issus de WSES/SIS-E 2018 et IDSA 2014.', refs:['has_peau19', 'wses_nsti18', 'idsa_ssti14', 'luyt_jni20', 'stevens88', 'babiker21']},
{id:'fournier', cat:'Peau / tissus mous', name:'Gangrène de Fournier (fasciite nécrosante périnéale et génitale)', site:'peau', epi:'Fasciite nécrosante du périnée, des organes génitaux externes et de la région périanale, pouvant s\'étendre à la paroi abdominale, aux cuisses et au rétropéritoine. Homme 50–60 ans surtout, femmes possibles. <b>FdR</b> : diabète (≈ 40–60 %), obésité, alcoolisme, immunodépression, artériopathie, insuffisance rénale ; <b>inhibiteurs de SGLT2 (gliflozines)</b> : alerte de pharmacovigilance → arrêter. <b>Porte d\'entrée</b> : anorectale (abcès, fistule, chirurgie, ≈ 30–50 %), urogénitale (sténose urétrale, sonde, chirurgie), cutanée. <b>Flore polymicrobienne</b> : E. coli et autres entérobactéries, Bacteroides et anaérobies, streptocoques, entérocoques, staphylocoques, Proteus, P. aeruginosa ; Candida possibles.', semio:'Douleur et œdème scrotal/périnéal intenses, érythème puis nécrose noirâtre, crépitation, odeur fétide, extension rapide le long des fascias (Colles, Scarpa, dartos) ; sepsis/choc fréquents. Testicules habituellement épargnés (vascularisation propre).', diag:'Diagnostic clinique → <b>bloc opératoire sans délai</b>. <b>TDM abdomino-pelvienne injectée</b> si elle ne retarde pas la chirurgie : extension (paroi, rétropéritoine), gaz, porte d\'entrée (abcès périanal, fistule). Hémocultures, prélèvements per-opératoires profonds (aéro/anaérobies, champignons). <b>Score FGSI</b> (Fournier Gangrene Severity Index, Laor 1995 : température, FC, FR, Na, K, créatinine, hématocrite, leucocytes, bicarbonates) : pronostic ; l\'UFGSI (âge, extension) prédit un peu mieux la mortalité ; le LRINEC est moins fiable.', proba:'<b>Chirurgie</b> : débridement en urgence de tous les tissus nécrosés (techniques d\'épargne cutanée de plus en plus utilisées), <b>reprise à 24–48 h</b> puis itérative ; <b>dérivation fécale</b> (colostomie ou système de gestion des selles) si atteinte du sphincter/périanale étendue ; <b>cystostomie sus-pubienne</b> si atteinte urétrale ; TPN puis greffe/lambeaux. Équipe : chirurgien digestif + urologue.<br><b>Antibiothérapie</b> (forte posologie) : <b>pipéracilline-tazobactam</b> (DC 4 g puis 16 g/j en continu) <b>+ clindamycine</b> 600–900 mg q8h (ou <b>linézolide</b> 600 mg q12h si FdR de SARM) <b>± amikacine</b> 25–30 mg/kg si choc ; <b>méropénème</b> à la place de la pip-tazo si colonisation/FdR de BLSE ; allergie : méropénème (si allergie non sévère) ou aztréonam + métronidazole + linézolide. Antifongique (échinocandine) si levures à l\'examen direct, choc et terrain à risque.', doc:'Désescalade selon les prélèvements per-opératoires en gardant une couverture anaérobie tant que persistent des débridements. Contrôle glycémique (insuline IV), arrêt des gliflozines, nutrition, prévention thrombo-embolique. Oxygénothérapie hyperbare : adjuvant optionnel, ne doit pas retarder les débridements.', duree:'Jusqu\'au contrôle de la source (plus de débridement nécessaire), stabilité hémodynamique, apyrexie ≥ 48 h et amélioration biologique ; habituellement 10–14 j. Des durées plus courtes après contrôle chirurgical semblent sans sur-risque (études rétrospectives).', div:'Pas de recommandation française spécifique ; synthèse des recommandations WSES/SIS-E 2018 (infections nécrosantes), HAS/SPILF/SFD 2019 et de revues récentes.', refs:['wses_nsti18', 'has_peau19', 'fournier_bjhm23', 'fournier_cur25']},
{id:'nocardiose', cat:'Bactérien opportuniste', name:'Nocardiose invasive (pulmonaire, cérébrale, disséminée)', site:'pulm', epi:'Nocardia : bacille Gram + filamenteux ramifié de l\'environnement (sol, poussières), acquisition surtout respiratoire. Atteint surtout les <b>déficits de l\'immunité cellulaire</b> : <b>transplantation d\'organe solide</b> (25–40 % des cas en Europe ; risque plus élevé après greffe cardiaque/pulmonaire ; tacrolimus, résiduels élevés d\'anticalcineurine, fortes doses de corticoïdes, maladie à CMV récente), corticothérapie, greffe de CSH, hémopathies traitées, biothérapies ; maladies pulmonaires chroniques (bronchectasies, mucoviscidose, BPCO sous corticoïdes). Chez un sujet « apparemment sain » : rechercher un déficit immunitaire primitif (granulomatose septique chronique) ou des <b>auto-anticorps anti-GM-CSF</b>. Le VIH est devenu une cause rare. Espèces fréquentes : N. farcinica, N. cyriacigeorgica, N. abscessus, N. nova, N. brasiliensis.', semio:'<b>Pulmonaire</b> (la plus fréquente) : nodules, masses excavées, consolidations, empyème, évolution subaiguë. <b>Cérébrale</b> : abcès souvent multiloculés, parfois <b>asymptomatiques</b>. <b>Cutanée</b> (primitive ou secondaire), <b>disséminée</b> (≥ 2 sites).', diag:'Examen direct (Gram : filaments ramifiés ; Ziehl modifié faiblement positif), <b>culture prolongée (2–3 semaines) à signaler au laboratoire</b>, PCR genre-spécifique ou 16S sur prélèvement ; identification d\'espèce et <b>antibiogramme indispensables</b> (sensibilité variable selon l\'espèce ; Observatoire français des nocardioses, Lyon). <b>Imagerie cérébrale systématique</b> (IRM) devant toute nocardiose, même sans symptôme neurologique ; TDM thoracique ; hémocultures (rarement positives).', proba:'<b>Cotrimoxazole</b> = pierre angulaire (Nocardia très souvent sensible) : <b>15 mg/kg/j de TMP</b> IV en 3–4 prises dans les formes graves (puis 10 mg/kg/j). <b>Linézolide</b> (sensibilité quasi constante) : alternative ou associé, 600 mg q12h (toxicité hématologique et neurologique au long cours). Associés possibles : <b>imipénème</b> (500 mg q6h à 1 g q6–8h), <b>amikacine</b> (15 mg/kg/j, STP ; diffusion cérébrale faible), C3G (céfotaxime/ceftriaxone, si S — N. farcinica souvent R).<br>• Forme cutanée primitive ou pulmonaire non grave : <b>monothérapie</b> (cotrimoxazole ou linézolide).<br>• Forme grave, disséminée ou <b>cérébrale</b> : <b>trithérapie</b> cotrimoxazole + imipénème + amikacine, ou cotrimoxazole + linézolide + carbapénème (préférer des molécules à bonne diffusion cérébrale si atteinte du SNC).', doc:'Adaptation à l\'espèce et à l\'antibiogramme ; relais oral (cotrimoxazole, linézolide, minocycline, moxifloxacine selon sensibilité) après amélioration. <b>Chirurgie</b> : drainage des abcès accessibles ; abcès cérébral si effet de masse important ou absence d\'amélioration après 2 sem de traitement. Diminuer l\'immunosuppression si possible.', duree:'<b>≈ 6 mois</b> dans la plupart des situations ; <b>≥ 12 mois</b> si atteinte cérébrale, forme disséminée ou immunodépression persistante ; durées plus courtes (&lt; 4 mois) possibles dans les formes à faible risque. Prophylaxie secondaire à discuter en cas d\'immunodépression définitive.', div:'Pas de recommandation formelle ; propositions d\'experts français (Observatoire des nocardioses) et européens.', refs:['lafont20', 'margalit21', 'ast_nocardia19']},
{id:'cand', cat:'Fongique', name:'Candidémie / candidose invasive', site:'bact',
 epi:'FdR : séjour prolongé, CVC, antibiothérapie large spectre, nutrition parentérale, chirurgie abdominale (fistules), EER, colonisation multisite.',
 semio:'—',
 diag:'Hémocultures (Se ≈ 50 %) ; β-D-glucane (bonne VPN) ; mannane/anti-mannane ; index de colonisation. Définitions FUNDICU 2024.',
 proba:'Traitement empirique en réanimation à discuter si choc septique inexpliqué + colonisation multisite + FdR (bénéfice non démontré, essai EMPIRICUS) ; arrêt si β-D-glucane négatif. Traitement : <b>échinocandine</b> 1re intention (ECMM 2025).',
 doc:'Désescalade fluconazole à J5–7 si souche S, patient stable, hémocultures négatives. Retrait du CVC, hémocultures quotidiennes, ETO si persistance.<br><b>Fond d\'œil dilaté</b> (ophtalmologue) dans la 1re semaine chez tout patient non neutropénique (après sortie d\'aplasie si neutropénie — IDSA 2016) : les échinocandines diffusent mal dans l\'œil → <b>si choriorétinite ou endophtalmie, changer d\'antifongique</b> : fluconazole (ou voriconazole) si souche S, sinon AmB liposomale ± flucytosine ; vitréite : + injection intravitréenne (AmB ou voriconazole) ± vitrectomie ; durée ≥ 4–6 sem jusqu\'à résolution des lésions. Lésions non spécifiques : pas de changement.<br>⚠ Caspofungine + EER continue : membranes PAN (AN69, AN69-ST, oXiris) à proscrire → set <b>HF1400 (PAES)</b> ou autre antifongique (cf. fiche caspofungine).',
 duree:'14 j après la 1re hémoculture négative (non compliquée).', div:'—', refs:['ecmm_cand25','idsa_cand16','fundicu24','ansm_caspo25','ema_caspo25','spilf_cand']},
{id:'aspergillose', cat:'Fongique', name:'Aspergillose invasive (dont aspergillose associée à la grippe — IAPA — et au COVID — CAPA)', site:'pulm', epi:'<b>Terrains classiques</b> : neutropénie prolongée, allogreffe de CSH, greffe d\'organe, hémopathies. <b>En réanimation</b> : corticothérapie, BPCO, cirrhose/hépatite alcoolique, <b>grippe grave</b> (IAPA, ≈ 10–20 % des grippes graves ventilées), <b>COVID-19</b> (CAPA), brûlés, ECMO. A. fumigatus majoritaire ; <b>résistance aux azolés</b> (TR34/L98H) en progression, de l\'ordre de quelques % en France.', semio:'Aggravation respiratoire sous antibiotiques, hémoptysie ; TDM : nodules, signe du halo, croissant gazeux, excavations (moins typiques chez le non-neutropénique) ; <b>trachéobronchite</b> pseudo-membraneuse ou ulcérée (IAPA) → fibroscopie systématique.', diag:'<b>Galactomannane LBA</b> (index ≥ 1,0) et sérique (≥ 0,5 ; peu sensible chez le non-neutropénique), <b>PCR Aspergillus</b> (LBA, sérum), culture ; β-D-glucane aspécifique. Définitions : <b>FUNDICU 2024</b> (réanimation), EORTC/MSGERC 2020 (immunodéprimés), critères IAPA/CAPA. Identification d\'espèce et <b>antifongigramme</b> (résistance aux azolés).', proba:'<b>Voriconazole</b> : J1 6 mg/kg q12h IV puis 4 mg/kg q12h (relais oral 200–300 mg q12h) ; <b>STP indispensable</b> (résiduelle cible ≈ 2–5 mg/L à J3–J5 ; nombreuses interactions : CI avec rifampicine, carbamazépine, phénobarbital ; tacrolimus/ciclosporine à réduire) ; ou <b>isavuconazole</b> 200 mg q8h J1–J2 puis 200 mg/j (efficacité équivalente, moins d\'effets indésirables hépatiques/visuels, moins d\'interactions, raccourcit le QT) ; ou posaconazole. <b>Amphotéricine B liposomale</b> 3 mg/kg/j si contre-indication aux azolés, résistance, ou forte prévalence locale de résistance. Association voriconazole + échinocandine à discuter dans les formes sévères. Chirurgie : hémoptysie grave, lésion au contact des gros vaisseaux.', doc:'Adapter à l\'antifongigramme ; réduire l\'immunosuppression/corticoïdes ; contrôle TDM (ne pas s\'alarmer d\'une augmentation précoce des lésions à la sortie d\'aplasie).', duree:'<b>≥ 6–12 sem</b> selon l\'évolution clinique et radiologique et la restauration immunitaire.', div:'—', refs:['escmid_asp18', 'fundicu24', 'eortc20']},
{id:'mucormycose', cat:'Fongique', name:'Mucormycose (rhino-orbito-cérébrale, pulmonaire, cutanée, disséminée)', site:'pulm', epi:'Mucorales (Rhizopus, Mucor, Lichtheimia, Rhizomucor, Cunninghamella). <b>FdR</b> : diabète déséquilibré/<b>acidocétose</b>, hémopathies et neutropénie prolongée, allogreffe de CSH, greffe d\'organe, corticothérapie, surcharge en fer (déféroxamine), traumatismes souillés, brûlures, COVID-19 sévère sous corticoïdes ; prophylaxie par voriconazole (sélection).', semio:'<b>Rhino-orbito-cérébrale</b> : douleur faciale, œdème, nécrose noirâtre des cornets/palais, ophtalmoplégie, cécité, atteinte du sinus caverneux. <b>Pulmonaire</b> : nodules, <b>signe du halo inversé</b>, &gt; 10 nodules, épanchement. Angio-invasion → thromboses, infarctus, nécrose. Évolution rapide.', diag:'Imagerie (TDM/IRM) pour l\'extension, <b>biopsie</b> (histologie : filaments larges non ou peu septés, ramifiés à angle droit ; culture ; PCR), <b>PCR Mucorales sérique</b> (sensible et précoce). <b>Galactomannane et β-D-glucane négatifs</b> (ne pas se laisser rassurer).', proba:'<b>Chirurgie</b> de débridement urgente et itérative (fortement recommandée). <b>Amphotéricine B liposomale</b> à forte dose en 1re intention : <b>5–10 mg/kg/j</b> (<b>10 mg/kg/j si atteinte cérébrale</b> ou greffé d\'organe). Alternatives : <b>isavuconazole</b> IV (200 mg q8h × 6 doses puis 200 mg/j) ou <b>posaconazole</b> IV/comprimés LP (300 mg q12h J1 puis 300 mg/j, STP) ; ces deux triazolés sont recommandés en sauvetage et en relais. Amphotéricine B désoxycholate déconseillée (toxicité). <b>Voriconazole et échinocandines inactifs</b>.', doc:'Corriger le terrain : équilibre glycémique et correction de l\'acidose, réduction de l\'immunosuppression/corticoïdes, arrêt de la déféroxamine, G-CSF si neutropénie.', duree:'Prolongée (semaines à mois) jusqu\'à résolution clinique et radiologique et restauration immunitaire ; relais oral par isavuconazole ou posaconazole.', div:'Recommandation internationale ECMM/MSG-ERC 2019 (« One World One Guideline »).', refs:['cornely_muco19', 'bdpm']},
{id:'pneumocystose', cat:'Fongique', name:'Pneumocystose (Pneumocystis jirovecii) — VIH et non-VIH', site:'pulm', epi:'<b>Non-VIH</b> (majoritaire en réanimation) : corticothérapie (≥ 20 mg/j de prednisone ≥ 4 sem), hémopathies, greffes (organe, CSH), chimiothérapies, anti-CD20, inhibiteurs de calcineurine, maladies auto-immunes traitées ; absence de prophylaxie. <b>VIH</b> : CD4 &lt; 200/mm³. La forme non-VIH est plus brutale et plus grave, avec une charge fongique plus faible.', semio:'Dyspnée et hypoxémie d\'aggravation rapide, toux sèche, fièvre ; auscultation pauvre ; pneumothorax possible. TDM : verre dépoli diffus bilatéral à prédominance péri-hilaire, kystes.', diag:'<b>PCR quantitative sur LBA</b> (excellente VPN ; une charge faible peut traduire une colonisation) ± immunofluorescence ; PCR sur expectoration induite/aspiration ; <b>β-D-glucane sérique</b> élevé (très bonne VPN) ; LDH élevées (aspécifique). Rechercher une co-infection (CMV, bactéries, Aspergillus).', proba:'<b>Cotrimoxazole IV 15–20 mg/kg/j de triméthoprime</b> en 3–4 prises (adapter à la fonction rénale ; relais oral dès que possible). <b>Pas d\'acide folinique</b> (plus d\'échecs). Alternatives si intolérance/échec : primaquine (après dosage de G6PD) + clindamycine ; pentamidine IV 4 mg/kg/j (toxicité : hypoglycémie, pancréatite, IRA, troubles du rythme) ; atovaquone (formes peu sévères). <b>Corticoïdes</b> : recommandés chez le <b>VIH</b> si PaO₂ &lt; 70 mmHg (prednisone 40 mg × 2/j 5 j, 40 mg/j 5 j, 20 mg/j 11 j, débutée dans les 72 h) ; <b>non-VIH</b> : bénéfice non démontré, à discuter au cas par cas (ECIL-5).', doc:'Surveillance : NFS, kaliémie (hyperkaliémie au triméthoprime), créatinine, transaminases, rash. Prophylaxie secondaire (cotrimoxazole) tant que l\'immunodépression persiste.', duree:'<b>21 j</b> (14–21 j chez le non-VIH à bonne évolution — ECIL-5).', div:'Pas de recommandation française dédiée ; ECIL-5 (non-VIH) et recommandations VIH.', refs:['ecil5pjp', 'safrin94', 'epopi']},
{id:'cryptococcose', cat:'Fongique', name:'Cryptococcose neuroméningée et disséminée', site:'snc', epi:'Cryptococcus neoformans (et C. gattii, possible chez l\'immunocompétent). <b>Terrain</b> : VIH (CD4 &lt; 100), greffe d\'organe, corticothérapie et immunosuppresseurs, hémopathies, cirrhose ; ≈ 20 % sans facteur identifié chez le non-VIH. Méningo-encéphalite subaiguë, plus insidieuse chez le non-VIH.', semio:'Céphalées, fièvre, confusion, <b>hypertension intracrânienne</b> (troubles visuels, paralysie du VI), parfois peu de syndrome méningé ; atteinte pulmonaire, cutanée, osseuse ; syndrome de reconstitution immunitaire (IRIS) après reprise des antirétroviraux ou levée de l\'immunosuppression.', diag:'<b>Antigène cryptococcique</b> (CrAg, test immunochromatographique) sérique et dans le LCS (très sensible) ; encre de Chine, culture du LCS (et sang, urines) ; <b>pression d\'ouverture</b> systématique à la PL ; IRM cérébrale ; TDM thoracique.', proba:'<b>Non-VIH (greffés, autres)</b> — induction : <b>amphotéricine B liposomale 3–4 mg/kg/j + flucytosine 100 mg/kg/j</b> (4 prises, STP : pic 30–80 mg/L, adapter à la fonction rénale) pendant <b>≥ 2 sem</b> (4–6 sem chez le non-VIH non greffé ou en cas d\'atteinte sévère/LCS non stérilisé) ; puis <b>consolidation fluconazole 400–800 mg/j 8 sem</b>, puis entretien 200 mg/j 6–12 mois.<br><b>VIH (OMS 2022, essai AMBITION)</b> : <b>dose unique d\'amphotéricine B liposomale 10 mg/kg</b> + flucytosine 100 mg/kg/j + fluconazole 1200 mg/j pendant 14 j ; puis fluconazole 800 mg/j 8 sem ; antirétroviraux après 4–6 sem.<br><b>HTIC</b> : si pression d\'ouverture ≥ 25 cmH₂O → <b>PL évacuatrices répétées</b> (quotidiennes jusqu\'à stabilisation, retrait de 20–30 mL jusqu\'à pression &lt; 20 cmH₂O ou réduction de 50 %) ; drain lombaire/DVE si réfractaire ; <b>pas</b> d\'acétazolamide, de mannitol ni de corticoïdes (sauf IRIS).', doc:'Échinocandines <b>inactives</b>. Contrôle de la culture du LCS à 2 sem (la négativation conditionne la consolidation).', duree:'Induction ≥ 2 sem → consolidation 8 sem → entretien 6–12 mois (VIH : jusqu\'à CD4 &gt; 100–200 et charge virale indétectable).', div:'Recommandation globale ECMM/ISHAM/ASM 2024 et OMS 2022 (VIH).', refs:['ecmm_crypto24', 'who_crypto22', 'epopi']},
{id:'moisissures_rares', cat:'Fongique', name:'Moisissures rares : Fusarium, Scedosporium, Lomentospora (et autres)', site:'pulm', epi:'Infections en augmentation chez les patients de réanimation et les immunodéprimés, favorisées par la pression de sélection des prophylaxies antifongiques ; souvent <b>résistances naturelles</b>. <b>Fusarium</b> : neutropénie prolongée, allogreffe, brûlés, kératites ; <b>Scedosporium</b> : quasi-noyade (eaux polluées), greffes, mucoviscidose ; <b>Lomentospora prolificans</b> : multirésistant, pronostic sombre.', semio:'Fusariose disséminée : fièvre, <b>lésions cutanées multiples</b> (papules/nodules nécrotiques), atteinte pulmonaire et sinusienne ; <b>hémocultures positives fréquentes</b> (contrairement à Aspergillus). Scedosporiose : pneumonie, abcès cérébraux (après noyade), atteintes ostéo-articulaires et oculaires.', diag:'Culture et identification d\'espèce (MALDI-TOF/séquençage), histologie (filaments septés difficiles à distinguer d\'Aspergillus), antifongigramme (CMI), β-D-glucane positif, galactomannane possiblement positif (Fusarium) ; biopsie cutanée précieuse.', proba:'<b>Fusarium</b> : <b>voriconazole</b> (STP) ou <b>amphotéricine B liposomale</b> 3–5 mg/kg/j, voire association initiale dans les formes graves en attendant les CMI. <b>Scedosporium</b> : <b>voriconazole</b> en 1re intention. <b>Lomentospora prolificans</b> : <b>voriconazole + terbinafine</b> (association associée à une meilleure survie dans les séries). <b>Échinocandines inactives</b>. Chirurgie de débridement des foyers accessibles ; réduction de l\'immunosuppression ; G-CSF si neutropénie.', doc:'Adapter aux CMI (laboratoire/CNR des mycoses invasives) ; isavuconazole/posaconazole en alternative selon CMI. Avis spécialisé systématique.', duree:'Prolongée (semaines à mois), jusqu\'à résolution et restauration immunitaire.', div:'Recommandation globale ECMM/ISHAM/ASM 2021.', refs:['hoenigl_moulds21', 'fundicu24']},
{id:'cauris', cat:'Fongique', name:'Candida auris (Candidozyma auris) — levure multirésistante émergente', site:'bact', epi:'Levure émergente responsable d\'épidémies hospitalières, notamment en réanimation ; <b>résistance au fluconazole quasi constante</b>, résistances possibles à l\'amphotéricine B et plus rarement aux échinocandines (pan-résistance décrite). Colonisation cutanée persistante (aisselles, plis inguinaux), survie prolongée sur les surfaces et le matériel. FdR : séjour en réanimation, CVC, ventilation, antibiotiques/antifongiques, hospitalisation récente dans un pays ou un établissement touché.', semio:'Candidémies, infections de cathéter, infections de plaie et urinaires ; mortalité élevée liée au terrain.', diag:'Identification par <b>MALDI-TOF</b> ou séquençage (erreurs fréquentes des méthodes biochimiques : confusion avec C. haemulonii, C. famata…). Antifongigramme systématique. <b>Dépistage</b> (aisselles + plis inguinaux ± autres sites) des patients contacts et des patients transférés d\'une zone/établissement à risque.', proba:'<b>Échinocandine</b> en 1re intention (caspofungine, micafungine, anidulafungine ; ⚠ pas de caspofungine sous EERc avec membrane AN69/oXiris) ; amphotéricine B liposomale si résistance/échec selon CMI. Retrait des cathéters. Pas de traitement de la simple colonisation.', doc:'<b>Mesures d\'hygiène</b> : alerte EOH, chambre individuelle, <b>précautions complémentaires contact</b>, matériel dédié, bionettoyage renforcé avec désinfectant actif (sporicide/chloré), dépistage des contacts, signalement.', duree:'Comme une candidémie : 14 j après la 1re hémoculture négative en l\'absence de complication.', div:'—', refs:['ecdc_cauris', 'ecmm_cand25']},
{id:'grippe', cat:'Viral', name:'Pneumopathies virales graves (grippe, COVID-19, VRS, métapneumovirus, adénovirus)', site:'pulm', epi:'Grippe saisonnière (H1N1, H3N2, B) ; COVID-19 ; VRS et métapneumovirus (sujet âgé, BPCO, immunodéprimé) ; adénovirus (immunodéprimé, collectivités). <b>Co-infections bactériennes</b> fréquentes dans la grippe : pneumocoque, <b>S. aureus</b> (dont PVL+), streptocoque A. <b>Aspergillose</b> associée (IAPA/CAPA).', semio:'Pneumonie hypoxémiante, SDRA ; myocardite, rhabdomyolyse, encéphalite (grippe).', diag:'PCR multiplex (écouvillon nasopharyngé ; aspiration trachéale/LBA chez le ventilé si PCR haute négative) ; PCT pour suspecter une co-infection bactérienne ; <b>galactomannane LBA</b> devant toute grippe grave qui s\'aggrave.', proba:'<b>Grippe</b> : <b>oseltamivir 75 mg × 2/j 5 j</b> dès la suspicion, <b>même au-delà de 48 h</b> chez le patient de réanimation ; 10 j chez l\'immunodéprimé ; administration par sonde ; adaptation rénale ; double dose non recommandée ; zanamivir IV si résistance (mutation H275Y). Pas de corticoïdes pour la grippe elle-même (hors hydrocortisone du choc septique). Co-infection suspectée : <b>céfotaxime</b> ± <b>linézolide</b> si pneumonie nécrosante/suspicion de S. aureus PVL+ (antitoxinique).<br><b>COVID-19</b> : <b>dexaméthasone 6 mg/j 10 j</b> si oxygéno-requérant ; tocilizumab ou baricitinib si aggravation ; anticoagulation préventive ; remdesivir chez l\'immunodéprimé ou en phase précoce.<br><b>VRS / métapneumovirus</b> : traitement symptomatique. <b>Adénovirus</b> disséminé de l\'immunodéprimé : cidofovir (avis).', doc:'Rechercher une aspergillose associée (IAPA/CAPA) si aggravation ; isolement gouttelettes (± air pour les gestes à risque).', duree:'Oseltamivir 5 j (10 j si immunodéprimé ou réplication persistante).', div:'—', refs:['idsa_flu18', 'idsa_covid', 'epopi']}
];
